# Application files may be installed anywhere under NAUPOSSYS. The data and
# per-user settings live outside the installed program so upgrades preserve them.
# POSsettings.json is intentionally stored in AppData: Program Files and
# other install destinations are normally not writable by a standard user.
settings_folder = Path(
    os.environ.get('APPDATA') or (Path.home() / '.config')
) / 'NAUPOSSYS'
settings_file = settings_folder / 'POSsettings.json'
google_token_file = settings_folder / 'google_finance_token.json'
google_finance_settings = None
google_finance_lock = threading.Lock()
google_backup_lock = threading.Lock()
customer_profile_lock = threading.Lock()
reservation_lock = threading.RLock()
ingredient_history_lock = threading.Lock()
ingredient_history_action_lock = threading.Lock()
cost_history_lock = threading.RLock()
version_history_lock = threading.RLock()

# Locks that become especially important under Python 3.14t/free-threading.
# They protect mutable shared state and write transactions while still allowing
# unrelated requests to run in parallel on different worker threads.
settings_lock = threading.RLock()
log_lock = threading.Lock()
ingredient_db_lock = threading.RLock()
recipe_db_lock = threading.RLock()
prep_recipe_lock = threading.RLock()
order_data_lock = threading.RLock()


def synchronized(
    lock
):

    def decorator(
        function
    ):

        @functools.wraps(
            function
        )
        def wrapped(
            *args,
            **kwargs
        ):

            with lock:

                return function(
                    *args,
                    **kwargs
                )

        return wrapped

    return decorator


