# ============================================================
# REDUNDANT STORAGE / LIVE BACKUP
# ============================================================

main_data_root = None
backup_data_root = None
active_data_root = None
storage_mode = 'MAIN'
storage_notice = None
storage_notice_id = 0
storage_notice_lock = threading.Lock()
storage_lock = threading.RLock()
storage_sync_lock = threading.Lock()
storage_recovery_lock = threading.Lock()
storage_monitor_stop = threading.Event()


def _as_nau_root(selected):
    selected = Path(selected).expanduser().resolve()
    return selected if selected.name.upper() == 'NAU' else selected / 'NAU'


def choose_backup_parent():
    """Choose a physically separate parent/folder for the live NAU backup."""
    def console_fallback(reason):
        if not os.isatty(0):
            raise RuntimeError(
                'Cannot open the backup folder picker or prompt in this session.'
            ) from reason
        selected = input(
            'Parent folder for NAU BACKUP (use a different drive/folder): '
        ).strip().strip('"')
        if not selected:
            raise RuntimeError('No backup location selected.')
        parent = Path(selected).expanduser().resolve()
        if not parent.is_dir():
            raise ValueError(f'Selected backup parent does not exist: {parent}')
        return parent

    try:
        import tkinter as tk
        from tkinter import filedialog
    except ImportError as error:
        return console_fallback(error)

    try:
        root = tk.Tk()
        root.withdraw()
        root.attributes('-topmost', True)
        try:
            selected = filedialog.askdirectory(
                parent=root,
                title='Select a DIFFERENT folder/drive for the NAU live backup',
                mustexist=True
            )
        finally:
            root.destroy()
    except tk.TclError as error:
        return console_fallback(error)

    if not selected:
        raise RuntimeError('Backup location selection was cancelled.')

    return Path(selected).expanduser().resolve()


def _roots_overlap(first, second):
    first = Path(first).resolve()
    second = Path(second).resolve()
    if first == second:
        return True
    try:
        first.relative_to(second)
        return True
    except ValueError:
        pass
    try:
        second.relative_to(first)
        return True
    except ValueError:
        return False


def _storage_root_healthy(root):
    try:
        root = Path(root)
        return (
            root.is_dir()
            and (root / 'DATABASE').is_dir()
            and (root / 'HISTORY').is_dir()
        )
    except OSError:
        return False


def _storage_root_reachable(root):
    """Verify a storage root is writable without cross-thread probe races."""
    try:
        root = Path(root)
        if not root.is_dir():
            return False

        # ThreadingHTTPServer + the storage monitor may probe at the same time.
        # A single fixed filename can be deleted by another thread on Windows,
        # producing a false "database unavailable" result.
        probe = root / (
            '.nau_storage_probe_'
            + str(os.getpid())
            + '_'
            + str(threading.get_ident())
            + '_'
            + uuid.uuid4().hex
        )

        try:
            probe.write_text('ok', encoding='utf-8')
            return probe.read_text(encoding='utf-8') == 'ok'
        finally:
            try:
                probe.unlink(missing_ok=True)
            except OSError:
                pass

    except OSError:
        return False


def _set_storage_notice(message):
    """Create one server-authoritative notification event."""
    global storage_notice, storage_notice_id

    text = str(message or '').strip()
    upper = text.upper()

    if 'MAIN DATABASE RESTORED' in upper:
        notice_type = 'main_restored'
        title = 'MAIN DATABASE RESTORED'
        tone = 'success'
    elif 'DATABASE FAILOVER' in upper or 'BACKUP DATABASE ACTIVE' in upper:
        notice_type = 'database_failover'
        title = 'BACKUP DATABASE ACTIVE'
        tone = 'warning'
    elif 'WARNING' in upper:
        notice_type = 'storage_warning'
        title = 'STORAGE WARNING'
        tone = 'warning'
    else:
        notice_type = 'storage'
        title = 'STORAGE NOTICE'
        tone = 'info'

    timestamp = datetime.now().astimezone().isoformat(timespec='milliseconds')

    with storage_notice_lock:
        storage_notice_id += 1
        storage_notice = {
            'id': f'{timestamp}-{storage_notice_id}',
            'sequence': storage_notice_id,
            'timestamp': timestamp,
            'type': notice_type,
            'title': title,
            'message': text,
            'tone': tone,
            'displayed': False,
            'displayed_at': None,
            'displayed_by': None
        }


def get_pending_storage_notice():
    """Return the current undisplayed notification without consuming it."""
    with storage_notice_lock:
        if not isinstance(storage_notice, dict):
            return None
        if storage_notice.get('displayed'):
            return None
        return dict(storage_notice)


def acknowledge_storage_notice(notice_id, client_name='POS'):
    """
    Mark a notification displayed only AFTER a frontend has actually rendered it.
    The ID check prevents an old tab from acknowledging a newer event.
    """
    global storage_notice

    with storage_notice_lock:
        if not isinstance(storage_notice, dict):
            return False

        if str(storage_notice.get('id')) != str(notice_id):
            return False

        if storage_notice.get('displayed'):
            return True

        storage_notice['displayed'] = True
        storage_notice['displayed_at'] = (
            datetime.now().astimezone().isoformat(timespec='milliseconds')
        )
        storage_notice['displayed_by'] = str(client_name or 'POS')[:100]
        return True




def get_storage_status():
    with storage_lock:
        return {
            'mode': storage_mode,
            'active_root': str(active_data_root) if active_data_root else None,
            'main_root': str(main_data_root) if main_data_root else None,
            'backup_root': str(backup_data_root) if backup_data_root else None,
            'main_available': (
                _storage_root_healthy(main_data_root)
                if main_data_root else False
            ),
            'backup_available': (
                _storage_root_healthy(backup_data_root)
                if backup_data_root else False
            ),
            'notice': dict(storage_notice) if storage_notice else None
        }


@synchronized(settings_lock)
def save_storage_locations(main_root, backup_root, active_root=None):
    settings = {}
    if settings_file.exists():
        settings = json.loads(settings_file.read_text(encoding='utf-8'))

    main_root = Path(main_root).resolve()
    backup_root = Path(backup_root).resolve()
    active_root = Path(active_root or main_root).resolve()

    settings.update({
        'version': 2,
        # Keep data_root for compatibility with older builds/tools.
        'data_root': str(active_root),
        'main_data_root': str(main_root),
        'backup_data_root': str(backup_root),
        'active_data_root': str(active_root)
    })
    save_pos_settings(settings)


def _copy_file_atomic(source, destination):
    source = Path(source)
    destination = Path(destination)
    destination.parent.mkdir(parents=True, exist_ok=True)

    temporary = destination.with_name(
        f'.{destination.name}.{os.getpid()}.{threading.get_ident()}.backup.tmp'
    )

    try:
        shutil.copy2(source, temporary)
        os.replace(temporary, destination)
    finally:
        temporary.unlink(missing_ok=True)


def sync_storage_tree(source_root=None, destination_root=None):
    """Make destination a file-for-file live mirror of source."""
    source_root = Path(source_root or active_data_root)
    destination_root = Path(destination_root or backup_data_root)

    if source_root.resolve() == destination_root.resolve():
        return

    if not _storage_root_healthy(source_root):
        raise RuntimeError(f'Source data root is unavailable: {source_root}')

    # The destination parent must still exist. We deliberately do not silently
    # recreate a missing removable/network drive at some unintended location.
    destination_parent = destination_root.parent
    if not destination_parent.is_dir():
        raise RuntimeError(
            f'Backup parent is unavailable: {destination_parent}'
        )

    with storage_sync_lock:
        destination_root.mkdir(parents=True, exist_ok=True)

        source_files = set()
        source_dirs = {Path('.')}

        for path in source_root.rglob('*'):
            relative = path.relative_to(source_root)

            if path.is_dir():
                source_dirs.add(relative)
                (destination_root / relative).mkdir(
                    parents=True,
                    exist_ok=True
                )
                continue

            if not path.is_file():
                continue

            # Probe/temp files are never part of the database.
            if path.name.startswith('.nau_storage_probe') or path.name.endswith('.tmp'):
                continue

            source_files.add(relative)
            target = destination_root / relative

            copy_needed = True
            try:
                if target.is_file():
                    source_stat = path.stat()
                    target_stat = target.stat()
                    copy_needed = (
                        source_stat.st_size != target_stat.st_size
                        or source_stat.st_mtime_ns != target_stat.st_mtime_ns
                    )
            except OSError:
                copy_needed = True

            if copy_needed:
                _copy_file_atomic(path, target)

        if destination_root.exists():
            for target in sorted(
                destination_root.rglob('*'),
                key=lambda p: len(p.parts),
                reverse=True
            ):
                relative = target.relative_to(destination_root)

                if target.is_file():

                    if _is_nau_managed_temp_file(
                        target
                    ):

                        # Old builds preserved orphaned temp files forever.
                        # This sync is serialized by storage_sync_lock, so
                        # managed temp files left here are safe to remove.
                        target.unlink(
                            missing_ok=True
                        )

                    elif (
                        relative not in source_files
                    ):

                        target.unlink(
                            missing_ok=True
                        )

                elif target.is_dir() and relative not in source_dirs:
                    try:
                        target.rmdir()
                    except OSError:
                        pass


def _write_storage_event_to_both(message):
    """Write a failover event even when the normal main log is unavailable."""
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    line = f'[{timestamp}] {message}\n'

    roots = []
    for root in (active_data_root, main_data_root, backup_data_root):
        if root is None:
            continue
        root = Path(root)
        if root not in roots:
            roots.append(root)

    for root in roots:
        try:
            if not root.is_dir():
                continue
            with open(root / 'NAU_LOG.txt', 'a', encoding='utf-8') as file:
                file.write(line)
                file.flush()
                os.fsync(file.fileno())
        except OSError:
            pass


def ensure_backup_database():
    """
    Ensure the configured BACKUP NAU database exists.

    If the selected backup location is reachable but its NAU database has been
    deleted/missing, recreate it automatically from MAIN. No frontend action or
    notification is required.

    Returns True only when a healthy backup database is available.
    """
    if backup_data_root is None:
        return False

    backup_root = Path(backup_data_root).resolve()

    if _storage_root_confirmed_available(backup_root):
        return True

    # We can only rebuild from MAIN when MAIN is currently healthy.
    if not _storage_root_confirmed_available(main_data_root):
        return False

    try:
        backup_root.mkdir(parents=True, exist_ok=True)

        sync_storage_tree(
            Path(main_data_root).resolve(),
            backup_root
        )

        if not _storage_root_healthy(backup_root):
            raise RuntimeError(
                'Backup recreation completed but health verification failed.'
            )

        print(
            'BACKUP DATABASE RECREATED | '
            f'Rebuilt missing backup from MAIN: {backup_root}',
            flush=True
        )

        return True

    except Exception as error:
        print(
            'BACKUP RECREATE ERROR | '
            f'Could not rebuild backup at {backup_root}: {error}',
            flush=True
        )
        return False


def _storage_root_confirmed_available(root, attempts=3, delay=0.12):
    """
    Require repeated successful structural + write checks before storage is
    considered usable. A transient Windows filesystem hiccup must not trigger
    database failover.
    """
    for attempt in range(max(1, attempts)):
        if _storage_root_healthy(root) and _storage_root_reachable(root):
            return True
        if attempt + 1 < attempts:
            time.sleep(delay)
    return False


def switch_to_backup(reason):
    global active_data_root, storage_mode

    with storage_lock:
        if storage_mode == 'BACKUP':
            return True

        # Never switch databases because of one transient failed probe.
        # Reconfirm MAIN immediately before committing the state change.
        if _storage_root_confirmed_available(main_data_root):
            active_data_root = Path(main_data_root).resolve()
            storage_mode = 'MAIN'
            configure_data_paths(active_data_root)
            return True

        if not _storage_root_confirmed_available(backup_data_root):
            # MAIN is already unavailable here, so a missing backup cannot be
            # rebuilt from MAIN at this instant. Keep the server-side error
            # only; the frontend no longer receives database notifications.
            message = (
                'CRITICAL STORAGE ERROR | Main database is unavailable and '
                'the backup database is also unavailable.'
            )
            print(message, flush=True)
            _write_storage_event_to_both(message)
            return False

        old_root = active_data_root
        active_data_root = Path(backup_data_root).resolve()
        storage_mode = 'BACKUP'
        configure_data_paths(active_data_root)

        message = (
            'DATABASE FAILOVER | Main database cannot be accessed or found. '
            f'Switched automatically to backup database: {active_data_root}. '
            f'Reason: {reason}'
        )

        print()
        print('!' * 72)
        print(message)
        print('!' * 72)
        print()

        _write_storage_event_to_both(message)

        try:
            save_storage_locations(
                main_data_root,
                backup_data_root,
                active_data_root
            )
        except Exception as error:
            print(
                f'WARNING: Could not persist backup failover state: {error}',
                flush=True
            )

        return True


def ensure_active_storage():
    """Check the active database before servicing a POS request."""
    with storage_lock:
        current = active_data_root
        mode = storage_mode

    if current is None:
        return False

    if _storage_root_confirmed_available(current):
        return True

    if mode == 'MAIN':
        return switch_to_backup(
            f'Active main root is unavailable: {current}'
        )

    message = (
        'CRITICAL STORAGE ERROR | Active backup database is unavailable: '
        f'{current}'
    )
    print(message, flush=True)
    _write_storage_event_to_both(message)
    return False


def mirror_after_change():
    """Mirror the active MAIN database after a successful mutation."""
    with storage_lock:
        if storage_mode != 'MAIN':
            return

    try:
        sync_storage_tree(active_data_root, backup_data_root)
    except Exception as error:
        message = (
            'BACKUP SYNC WARNING | Main database is still active, but the '
            f'backup could not be synchronized: {error}'
        )
        print(message, flush=True)
        _write_storage_event_to_both(message)


def storage_tree_signature(root):
    """
    Return a deterministic signature of the mirrored data tree.
    File contents are hashed so recovery is verified before MAIN becomes active.
    """
    root = Path(root)

    if not _storage_root_healthy(root):
        raise RuntimeError(
            f'Cannot verify unavailable storage root: {root}'
        )

    digest = hashlib.sha256()
    file_count = 0

    for path in sorted(
        (
            item
            for item in root.rglob('*')
            if item.is_file()
            and item.name != '.nau_storage_probe'
            and not item.name.endswith('.tmp')
        ),
        key=lambda item: str(item.relative_to(root)).lower()
    ):
        relative = path.relative_to(root).as_posix()
        digest.update(relative.encode('utf-8'))
        digest.update(b'\0')

        with open(path, 'rb') as file:
            while True:
                chunk = file.read(1024 * 1024)
                if not chunk:
                    break
                digest.update(chunk)

        digest.update(b'\0')
        file_count += 1

    return file_count, digest.hexdigest()


def recover_main_from_backup():
    """
    While BACKUP is authoritative:
      1. confirm MAIN is writable,
      2. keep serving POS from BACKUP,
      3. copy BACKUP -> MAIN,
      4. verify both trees match,
      5. only then switch back to MAIN,
      6. resume normal MAIN -> BACKUP mirroring.
    """
    global active_data_root, storage_mode

    if not storage_recovery_lock.acquire(blocking=False):
        return False

    try:
        with storage_lock:
            if storage_mode != 'BACKUP':
                return False

            authoritative_backup = Path(active_data_root).resolve()
            restored_main = Path(main_data_root).resolve()

        # MAIN must exist and accept a write probe before we touch it.
        if not _storage_root_healthy(restored_main):
            return False

        if not _storage_root_reachable(restored_main):
            return False

        if not _storage_root_healthy(authoritative_backup):
            return False

        print(
            f'MAIN DATABASE DETECTED | Restoring from authoritative backup: '
            f'{authoritative_backup} -> {restored_main}',
            flush=True
        )

        # BACKUP remains active throughout this entire synchronization.
        sync_storage_tree(
            authoritative_backup,
            restored_main
        )

        backup_signature = storage_tree_signature(
            authoritative_backup
        )
        main_signature = storage_tree_signature(
            restored_main
        )

        if backup_signature != main_signature:
            raise RuntimeError(
                'Backup-to-main verification failed. MAIN was not activated.'
            )

        # Final short critical section: BACKUP is still authoritative until
        # verification has passed. Then repoint all data paths to MAIN.
        with storage_lock:
            if storage_mode != 'BACKUP':
                return False

            active_data_root = restored_main
            storage_mode = 'MAIN'
            configure_data_paths(
                active_data_root
            )

            save_storage_locations(
                main_data_root,
                backup_data_root,
                active_data_root
            )

            message = (
                'MAIN DATABASE RESTORED | Main database is available again. '
                'Backup data was synchronized to Main and verified successfully. '
                'POS switched back to the Main database.'
            )

        print()
        print('=' * 72)
        print(message)
        print('=' * 72)
        print()

        _write_storage_event_to_both(
            message
        )

        # MAIN is authoritative again. One normal mirror pass confirms BACKUP
        # remains aligned after the switch.
        try:
            sync_storage_tree(
                active_data_root,
                backup_data_root
            )
        except Exception as error:
            warning = (
                'BACKUP SYNC WARNING | Main database was restored, but the '
                f'post-recovery backup confirmation failed: {error}'
            )
            print(
                warning,
                flush=True
            )
            _write_storage_event_to_both(
                warning
            )

        return True

    except Exception as error:
        # Never switch away from BACKUP when restoration or verification fails.
        message = (
            'MAIN RECOVERY WARNING | Main database was detected, but restoring '
            f'Backup to Main failed. POS remains on Backup. Reason: {error}'
        )
        print(
            message,
            flush=True
        )
        _write_storage_event_to_both(
            message
        )
        return False

    finally:
        storage_recovery_lock.release()


def storage_monitor_loop():
    """
    Every 2 seconds:
      - MAIN mode: detect loss and fail over to BACKUP.
      - BACKUP mode: detect MAIN returning, restore BACKUP -> MAIN, verify,
        then switch back to MAIN.
    """
    while not storage_monitor_stop.wait(2.0):
        try:
            if storage_mode == 'BACKUP':
                recover_main_from_backup()
            else:
                ensure_active_storage()

                # While MAIN is healthy, automatically recreate a deleted or
                # missing backup database in the already-selected backup path.
                ensure_backup_database()

        except Exception as error:
            print(
                f'STORAGE MONITOR ERROR | {error}',
                flush=True
            )


def resolve_redundant_storage():
    """
    First setup asks for MAIN and BACKUP locations.
    Existing v1 installs keep their current main location and are prompted once
    for a backup location. If MAIN is missing, BACKUP is selected automatically.
    """
    global main_data_root, backup_data_root, active_data_root, storage_mode

    first_settings = not settings_file.exists()

    if first_settings:
        main_parent = choose_data_parent()
        main_root = _as_nau_root(main_parent)

        backup_parent = choose_backup_parent()
        backup_root = _as_nau_root(backup_parent)

        if _roots_overlap(main_root, backup_root):
            raise ValueError(
                'Main and backup locations must be different and cannot be '
                'inside each other.'
            )

        main_data_root = main_root
        backup_data_root = backup_root
        active_data_root = main_root
        storage_mode = 'MAIN'
        return main_root, True, _storage_root_healthy(main_root), True

    settings = json.loads(settings_file.read_text(encoding='utf-8'))
    version = settings.get('version', 1)

    if version == 1:
        raw_main = settings.get('data_root')
        if not isinstance(raw_main, str) or not Path(raw_main).is_absolute():
            raise ValueError('POSsettings.json has an invalid data_root.')

        main_root = Path(raw_main).resolve()
        backup_parent = choose_backup_parent()
        backup_root = _as_nau_root(backup_parent)

        if _roots_overlap(main_root, backup_root):
            raise ValueError(
                'Main and backup locations must be different and cannot be '
                'inside each other.'
            )

        main_data_root = main_root
        backup_data_root = backup_root

        if _storage_root_healthy(main_root):
            active_data_root = main_root
            storage_mode = 'MAIN'
            return main_root, False, True, True

        if _storage_root_healthy(backup_root):
            active_data_root = backup_root
            storage_mode = 'BACKUP'
            return backup_root, False, True, True

        raise RuntimeError(
            'The existing main database is unavailable and the newly selected '
            'backup does not contain a usable NAU database.'
        )

    if version != 2:
        raise ValueError(
            f'Unsupported POSsettings.json version: {version}'
        )

    raw_main = settings.get('main_data_root')
    raw_backup = settings.get('backup_data_root')
    raw_active = settings.get('active_data_root') or settings.get('data_root')

    for label, value in (
        ('main_data_root', raw_main),
        ('backup_data_root', raw_backup),
        ('active_data_root', raw_active)
    ):
        if not isinstance(value, str) or not Path(value).is_absolute():
            raise ValueError(f'POSsettings.json has invalid {label}.')

    main_data_root = Path(raw_main).resolve()
    backup_data_root = Path(raw_backup).resolve()
    saved_active = Path(raw_active).resolve()

    if _roots_overlap(main_data_root, backup_data_root):
        raise ValueError(
            'Main and backup locations must be different and cannot be '
            'inside each other.'
        )

    if saved_active == backup_data_root:
        if _storage_root_healthy(backup_data_root):
            active_data_root = backup_data_root
            storage_mode = 'BACKUP'
            return backup_data_root, False, True, False

        if _storage_root_healthy(main_data_root):
            active_data_root = main_data_root
            storage_mode = 'MAIN'
            ensure_backup_database()
            return main_data_root, False, True, False

    else:
        if _storage_root_healthy(main_data_root):
            active_data_root = main_data_root
            storage_mode = 'MAIN'
            ensure_backup_database()
            return main_data_root, False, True, False

        if _storage_root_healthy(backup_data_root):
            active_data_root = backup_data_root
            storage_mode = 'BACKUP'
            return backup_data_root, False, True, False

    raise RuntimeError(
        'Neither the main nor backup NAU database can be accessed.'
    )



def choose_data_parent():
    """Select the parent folder or the NAU folder containing the POS data."""
    def console_fallback(reason):
        if not os.isatty(0):
            raise RuntimeError('Cannot open the folder picker or prompt in this session.') from reason
        selected = input('Parent folder for NAU data (e.g. D:\\POSData): ').strip().strip('"')
        if not selected:
            raise RuntimeError('No data location selected.')
        parent = Path(selected).expanduser().resolve()
        if not parent.is_dir():
            raise ValueError(f'Selected parent folder does not exist: {parent}')
        return parent

    try:
        import tkinter as tk
        from tkinter import filedialog
    except ImportError as error:
        return console_fallback(error)
    try:
        root = tk.Tk()
        root.withdraw()
        root.attributes('-topmost', True)
        try:
            selected = filedialog.askdirectory(
                parent=root,
                title='Select the NAU folder or its parent folder for POS data',
                mustexist=True
            )
        finally:
            root.destroy()
    except tk.TclError as error:
        return console_fallback(error)
    if not selected:
        raise RuntimeError('Data location selection was cancelled.')
    return Path(selected).expanduser().resolve()


def confirm_missing_database(candidate):
    """Ask before creating or relocating data when the saved database is gone."""
    question = (
        'DATABASE not found. Do you want to create a new database?\n\n'
        f'Saved location: {candidate}\n\n'
        'Choose Yes to select a folder. If it already has a NAU database, '
        'the server will use that database. Choose No to quit.'
    )
    try:
        import tkinter as tk
        from tkinter import messagebox
    except ImportError as error:
        if not os.isatty(0):
            raise RuntimeError('Cannot show database confirmation in this session.') from error
        return input(question + '\nContinue? [y/N]: ').strip().lower() == 'y'
    try:
        root = tk.Tk()
        root.withdraw()
        root.attributes('-topmost', True)
        try:
            return messagebox.askyesno('DATABASE not found', question, parent=root)
        finally:
            root.destroy()
    except tk.TclError as error:
        if not os.isatty(0):
            raise RuntimeError('Cannot show database confirmation in this session.') from error
        return input(question + '\nContinue? [y/N]: ').strip().lower() == 'y'


def resolve_data_root():
    """Read saved data location; ask before choosing a replacement if missing."""
    first_run = not settings_file.exists()
    if first_run:
        parent = choose_data_parent()
        if not parent.is_dir():
            raise ValueError(f'Selected parent folder does not exist: {parent}')
        candidate = parent if parent.name.upper() == 'NAU' else parent / 'NAU'
    else:
        try:
            settings = json.loads(settings_file.read_text(encoding='utf-8'))
        except (OSError, json.JSONDecodeError) as error:
            raise RuntimeError(
                f'Cannot read {settings_file}. Repair it or rename it to choose again.'
            ) from error
        if not isinstance(settings, dict) or settings.get('version') != 1:
            raise ValueError(f'Invalid POSsettings.json format: {settings_file}')
        raw_root = settings.get('data_root')
        if not isinstance(raw_root, str) or not Path(raw_root).is_absolute():
            raise ValueError(f'POSsettings.json needs an absolute data_root: {settings_file}')
        candidate = Path(raw_root)
        if candidate.name.upper() != 'NAU':
            raise ValueError(f'Data root must be a folder named NAU: {candidate}')

    while True:
        candidate = candidate.resolve()
        if candidate.exists() and not candidate.is_dir():
            raise ValueError(f'Data root is not a folder: {candidate}')
        db_exists = (candidate / 'DATABASE').is_dir()
        history_exists = (candidate / 'HISTORY').is_dir()
        if db_exists != history_exists:
            raise RuntimeError(
                f'Incomplete data folder at {candidate}: DATABASE and HISTORY '
                'must both exist or both be absent. Nothing has been overwritten.'
            )
        if first_run or (db_exists and history_exists):
            return candidate, first_run, db_exists
        if not confirm_missing_database(candidate):
            print('Database selection declined. Server stopped.')
            raise SystemExit(0)
        try:
            selected = choose_data_parent()
        except RuntimeError as error:
            if 'cancelled' in str(error).lower():
                print('Database selection cancelled. Server stopped.')
                raise SystemExit(0) from None
            raise
        candidate = selected if selected.name.upper() == 'NAU' else selected / 'NAU'
        first_run = True  # Save the new location after successful initialization.


def configure_data_paths(root):
    global nau_folder, assets_folder, temps_folder, order_data_folder
    global database_folder, ingredients_folder, recipes_folder, prep_recipe_folder
    global special_recipes_folder, shot_recipe_file, bespoke_recipe_file, classic_recipe_file, misc_folder, promocode_file
    global point_reward_promocode_file, recipe_categories_file
    global history_folder, sales_history_folder, pending_sales_folder
    global pending_adjustments_folder, ingredient_history_folder, ingredient_history_state_file
    global cost_history_folder, cost_history_file
    global version_history_folder, ingredient_version_history_folder, recipe_version_history_folder
    global customers_folder, reservations_file, log_file, sales_file

    nau_folder = root
    assets_folder = root / 'ASSETS'
    temps_folder = root / 'TEMPS'
    order_data_folder = temps_folder / 'ORDER DATA'
    database_folder = root / 'DATABASE'
    ingredients_folder = database_folder / 'ingredients'
    recipes_folder = database_folder / 'recipes'
    prep_recipe_folder = recipes_folder / 'prep recipe'
    special_recipes_folder = recipes_folder / 'specials'
    shot_recipe_file = special_recipes_folder / 'SHOT.json'
    bespoke_recipe_file = special_recipes_folder / 'BESPOKE.json'
    classic_recipe_file = special_recipes_folder / 'CLASSIC.json'
    misc_folder = database_folder / 'misc'
    promocode_file = misc_folder / 'PROMOCODE.json'
    point_reward_promocode_file = misc_folder / 'POINT_REWARD_PROMO.json'
    recipe_categories_file = misc_folder / 'RECIPE_CATEGORIES.json'
    history_folder = root / 'HISTORY'
    sales_history_folder = history_folder / 'SALES'
    pending_sales_folder = history_folder / 'PENDING_SALES'
    pending_adjustments_folder = history_folder / 'PENDING_ADJUSTMENTS'
    ingredient_history_folder = history_folder / 'INGREDIENTS'
    ingredient_history_state_file = ingredient_history_folder / '_undo_redo_state.json'
    cost_history_folder = history_folder / 'COSTS'
    cost_history_file = cost_history_folder / 'cost_history.json'
    version_history_folder = history_folder / 'VERSIONS'
    ingredient_version_history_folder = version_history_folder / 'INGREDIENTS'
    recipe_version_history_folder = version_history_folder / 'RECIPES'
    customers_folder = database_folder / 'customers'
    reservations_file = database_folder / 'reservations.json'
    log_file = root / 'NAU_LOG.txt'
    sales_file = root / 'NAU_SALES.txt'


@synchronized(settings_lock)
def save_pos_settings(settings):
    settings_folder.mkdir(parents=True, exist_ok=True)
    temporary = settings_file.with_suffix('.json.tmp')
    try:
        temporary.write_text(
            json.dumps(settings, indent=2),
            encoding='utf-8'
        )
        os.replace(temporary, settings_file)
    finally:
        temporary.unlink(missing_ok=True)


@synchronized(settings_lock)
def save_data_location(root):
    # Compatibility wrapper. New builds persist both MAIN and BACKUP roots.
    if main_data_root is not None and backup_data_root is not None:
        save_storage_locations(
            main_data_root,
            backup_data_root,
            active_data_root or root
        )
        return

    settings = {}
    if settings_file.exists():
        settings = json.loads(settings_file.read_text(encoding='utf-8'))
    settings.update({'version': 1, 'data_root': str(root)})
    save_pos_settings(settings)


def choose_google_client_file():
    """Ask for a Desktop OAuth JSON file; None leaves finance sync disabled."""
    def console_fallback(error):
        if not os.isatty(0):
            raise RuntimeError('Cannot prompt for Google setup in this session.') from error
        answer = input('Set up Google Sheets finance sync now? [y/N]: ').strip().lower()
        if answer != 'y':
            return None
        return Path(input('Path to Desktop OAuth client JSON: ').strip().strip('"'))

    try:
        import tkinter as tk
        from tkinter import filedialog, messagebox
    except ImportError as error:
        return console_fallback(error)
    try:
        root = tk.Tk()
        root.withdraw()
        root.attributes('-topmost', True)
        try:
            enabled = messagebox.askyesno(
                'NAU Finance Google Sheets',
                'Connect finance to Google Sheets?\n\n'
                'Choose Yes to select a Google OAuth Desktop client JSON file.\n'
                'Choose No to set up Google Sheets later.',
                parent=root
            )
            if not enabled:
                return None
            chosen = filedialog.askopenfilename(
                parent=root,
                title='Select your Google OAuth Desktop client JSON file',
                filetypes=[('JSON files', '*.json'), ('All files', '*.*')]
            )
        finally:
            root.destroy()
        if not chosen:
            raise RuntimeError('Google client file selection was cancelled.')
        return Path(chosen)
    except tk.TclError as error:
        return console_fallback(error)


def bundled_google_client_file():
    """Locate the Desktop OAuth JSON supplied in the PyInstaller EXE or beside it."""
    candidates = []
    bundle_folder = getattr(sys, '_MEIPASS', None)
    if bundle_folder:
        candidates.append(Path(bundle_folder) / 'google_finance_client.json')
        candidates.append(Path(sys.executable).resolve().parent / 'google_finance_client.json')
    else:
        candidates.append(Path(__file__).resolve().parent / 'google_finance_client.json')
    return next((file for file in candidates if file.is_file()), None)


def configure_google_finance(force=False):
    """Save Google setup beside POSsettings; never put credentials in Program Files."""
    global google_finance_settings
    settings = json.loads(settings_file.read_text(encoding='utf-8'))
    if force or 'google_finance' not in settings:
        source = choose_google_client_file() if force else bundled_google_client_file()
        if source is None and not force:
            source = choose_google_client_file()
        if source is None:
            settings['google_finance'] = {'enabled': False}
        else:
            source = source.expanduser().resolve()
            client = json.loads(source.read_text(encoding='utf-8'))
            installed = client.get('installed', {})
            if not installed.get('client_id') or not installed.get('client_secret'):
                raise ValueError('Select a Google OAuth client JSON of type Desktop app.')
            destination = settings_folder / 'google_finance_client.json'
            settings_folder.mkdir(parents=True, exist_ok=True)
            if source != destination:
                shutil.copyfile(source, destination)
            settings['google_finance'] = {
                'enabled': True,
                'client_file': str(destination)
            }
            google_token_file.unlink(missing_ok=True)
        save_pos_settings(settings)
    google_finance_settings = settings['google_finance']
    if not isinstance(google_finance_settings, dict):
        raise ValueError('Invalid google_finance settings in POSsettings.json.')
    return google_finance_settings.get('enabled') is True


HOST = '127.0.0.1'
PORT = 8000
SERVER_BUILD = 'public-pos-no-remote-no-camera-2026-10-23'


# ============================================================
# SERVER CONCURRENCY — NATIVE FREE-THREADED MODEL
#
# This server is intentionally single-process and multi-threaded.
#
# On Python 3.14t with the GIL disabled, HTTP worker threads can execute
# Python code genuinely in parallel across CPU cores while still sharing
# the same auth sessions, locks, failover state, and in-memory POS state.
#
# On a normal GIL-enabled Python build the same architecture remains safe
# and concurrent for I/O, but CPU-bound Python bytecode will not run in
# parallel. The startup console explicitly reports which mode is active.
# ============================================================

LOGICAL_CPU_COUNT = max(
    1,
    os.cpu_count()
    or 1
)


def _read_worker_setting(
    name,
    default_value,
    minimum,
    maximum
):

    raw = str(
        os.environ.get(
            name,
            ''
        )
        or ''
    ).strip()

    if not raw:

        return default_value

    try:

        value = int(
            raw
        )

    except Exception:

        return default_value

    return max(
        minimum,
        min(
            maximum,
            value
        )
    )


def detect_gil_enabled():

    checker = getattr(
        sys,
        '_is_gil_enabled',
        None
    )

    if checker is None:

        return None

    try:

        return bool(
            checker()
        )

    except Exception:

        return None


GIL_ENABLED = detect_gil_enabled()


FREE_THREADED_BUILD = bool(
    sysconfig.get_config_var(
        'Py_GIL_DISABLED'
    )
)


FREE_THREADED_PARALLELISM = (
    FREE_THREADED_BUILD
    and
    GIL_ENABLED is False
)


# One worker per logical CPU by default gives the free-threaded build enough
# runnable Python threads to use the machine, while keeping the pool bounded.
# A minimum of 8 is useful on smaller systems because POS work also contains
# disk/network waits. Override with NAU_HTTP_THREADS when desired.
DEFAULT_HTTP_WORKER_THREADS = max(
    8,
    min(
        64,
        LOGICAL_CPU_COUNT
    )
)


HTTP_WORKER_THREADS = _read_worker_setting(
    'NAU_HTTP_THREADS',
    DEFAULT_HTTP_WORKER_THREADS,
    2,
    128
)


request_metrics_lock = threading.Lock()
active_http_requests = 0
peak_http_requests = 0
completed_http_requests = 0


def encode_json_payload(
    data
):

    # Encoding happens directly on the request worker thread. Under Python
    # 3.14t/free-threading, separate request threads can execute this and other
    # Python work on different CPU cores at the same time.
    return json.dumps(
        data,
        ensure_ascii=False,
        separators=(
            ',',
            ':'
        )
    ).encode(
        'utf-8'
    )


def get_server_concurrency_status():

    with request_metrics_lock:

        active_requests = (
            active_http_requests
        )

        peak_requests = (
            peak_http_requests
        )

        completed_requests = (
            completed_http_requests
        )

    return {
        'logical_cpus':
            LOGICAL_CPU_COUNT,

        'http_worker_threads':
            HTTP_WORKER_THREADS,

        'free_threaded_build':
            FREE_THREADED_BUILD,

        'gil_enabled':
            GIL_ENABLED,

        'free_threaded_parallelism':
            FREE_THREADED_PARALLELISM,

        'current_worker_thread':
            threading.current_thread().name,

        'current_worker_native_id':
            getattr(
                threading.current_thread(),
                'native_id',
                None
            ),

        'active_http_requests':
            active_requests,

        'peak_http_requests':
            peak_requests,

        'completed_http_requests':
            completed_requests,

        'model':
            'NATIVE_SHARED_MEMORY_THREAD_POOL'
    }


class NAUThreadPoolHTTPServer(
    HTTPServer
):

    allow_reuse_address = True


    def __init__(
        self,
        server_address,
        request_handler_class,
        max_workers
    ):

        super().__init__(
            server_address,
            request_handler_class
        )

        self.request_executor = ThreadPoolExecutor(
            max_workers=
                max_workers,

            thread_name_prefix=
                'nau-http'
        )

        # Bound worker + queued HTTP work. The business-action queue is the
        # intentional place where unique requests may wait. Raw sockets are not.
        self.request_slots = threading.BoundedSemaphore(
            max_workers * 2
        )


    def process_request(
        self,
        request,
        client_address
    ):

        if not self.request_slots.acquire(
            blocking=False
        ):
            try:
                body = encode_json_payload(
                    json_response(
                        False,
                        {
                            'rate_limited': True,
                            'server_gate_full': True
                        },
                        error='Too many requests. Please try again shortly.'
                    )
                )
                response = (
                    b'HTTP/1.1 429 Too Many Requests\r\n'
                    b'Content-Type: application/json; charset=utf-8\r\n'
                    b'Access-Control-Allow-Origin: *\r\n'
                    b'Connection: close\r\n'
                    + f'Content-Length: {len(body)}\r\n'.encode('ascii')
                    + b'\r\n'
                    + body
                )
                request.sendall(response)
            except Exception:
                pass
            finally:
                self.shutdown_request(request)
            return

        try:

            self.request_executor.submit(
                self._process_request_worker,
                request,
                client_address
            )

        except Exception:

            self.request_slots.release()

            self.shutdown_request(
                request
            )

            raise


    def _process_request_worker(
        self,
        request,
        client_address
    ):

        global active_http_requests
        global peak_http_requests
        global completed_http_requests

        with request_metrics_lock:

            active_http_requests += 1

            if (
                active_http_requests >
                peak_http_requests
            ):

                peak_http_requests = (
                    active_http_requests
                )

        try:

            self.finish_request(
                request,
                client_address
            )

        except Exception:

            self.handle_error(
                request,
                client_address
            )

        finally:

            with request_metrics_lock:

                active_http_requests = max(
                    0,
                    active_http_requests - 1
                )

                completed_http_requests += 1

            self.request_slots.release()

            self.shutdown_request(
                request
            )


    def server_close(
        self
    ):

        try:

            self.request_executor.shutdown(
                wait=True,
                cancel_futures=True
            )

        finally:

            super().server_close()



# ============================================================
# TEMP / STAGING CLEANUP
#
# Atomic writes and live-mirror copies intentionally use hidden
# *.tmp files, then os.replace() them into place. Under a normal
# shutdown those files disappear immediately.
#
# If Windows kills the process, the PC loses power, or Python is
# terminated during a copy, an orphaned temp file can remain.
# Older builds deliberately ignored *.tmp during mirror cleanup,
# which meant those abandoned files could accumulate forever.
# ============================================================

def _nau_server_is_already_listening():

    try:

        with socket.create_connection(
            (
                HOST,
                PORT
            ),
            timeout=0.20
        ):

            return True

    except OSError:

        return False


def _is_nau_managed_temp_file(
    path
):

    name = Path(
        path
    ).name

    if name.startswith(
        '.nau_storage_probe'
    ):

        return True

    return (
        name.startswith(
            '.'
        )
        and
        name.endswith(
            '.tmp'
        )
    )


def cleanup_nau_temp_artifacts(
    remove_cloud_staging=True
):

    removed_files = 0

    removed_bytes = 0

    removed_staging_bytes = 0


    # Never touch possible in-flight temp files if another NAU server
    # is already bound to the POS port.
    if _nau_server_is_already_listening():

        print(
            'TEMP CLEANUP SKIPPED | '
            'Another server is already listening on the POS port.',
            flush=True
        )

        return {
            'removed_files':
                0,

            'removed_bytes':
                0,

            'removed_staging_bytes':
                0,

            'skipped':
                True
        }


    roots = []

    for root in (
        main_data_root,
        backup_data_root,
        active_data_root
    ):

        if root is None:

            continue

        root = Path(
            root
        )

        try:

            resolved = root.resolve()

        except Exception:

            resolved = root

        if resolved not in roots:

            roots.append(
                resolved
            )


    for root in roots:

        if not root.exists():

            continue

        try:

            candidates = list(
                root.rglob(
                    '*'
                )
            )

        except OSError:

            continue

        for path in candidates:

            try:

                if (
                    not path.is_file()
                    or
                    not _is_nau_managed_temp_file(
                        path
                    )
                ):

                    continue

                try:

                    file_size = path.stat().st_size

                except OSError:

                    file_size = 0

                path.unlink(
                    missing_ok=True
                )

                removed_files += 1

                removed_bytes += (
                    file_size
                )

            except OSError:

                # A locked temp file is left alone rather than risking
                # interruption of another process.
                continue


    # Settings/token atomic-write leftovers use fixed names.
    for path in (
        settings_file.with_suffix(
            '.json.tmp'
        ),
        google_token_file.with_suffix(
            '.json.tmp'
        )
    ):

        try:

            if path.is_file():

                file_size = path.stat().st_size

                path.unlink(
                    missing_ok=True
                )

                removed_files += 1

                removed_bytes += (
                    file_size
                )

        except OSError:

            pass


    if remove_cloud_staging:

        snapshot_parent = (
            settings_folder /
            'cloud_backup_staging'
        )

        if snapshot_parent.exists():

            try:

                for path in snapshot_parent.rglob(
                    '*'
                ):

                    try:

                        if path.is_file():

                            removed_staging_bytes += (
                                path.stat().st_size
                            )

                    except OSError:

                        pass

                shutil.rmtree(
                    snapshot_parent,
                    ignore_errors=False
                )

            except OSError:

                # If Windows still has one file open, leave the staging
                # directory for the normal Google-backup cleanup pass.
                pass


    total_removed_bytes = (
        removed_bytes +
        removed_staging_bytes
    )


    if (
        removed_files >
        0
        or
        removed_staging_bytes >
        0
    ):

        print(
            'TEMP CLEANUP COMPLETE | '
            f'FILES={removed_files} | '
            f'BYTES={total_removed_bytes}',
            flush=True
        )


    return {
        'removed_files':
            removed_files,

        'removed_bytes':
            removed_bytes,

        'removed_staging_bytes':
            removed_staging_bytes,

        'skipped':
            False
    }




SODA_UNIT = 'can'
SODA_COST_PER_UNIT = Decimal('12000')

MONEY_PLACES = Decimal('0.01')

CUSTOMER_POINTS_SPEND_VND = Decimal('100000')
CUSTOMER_POINTS_PER_BLOCK = 10

SPECIAL_PROMO_POINTS_FREE_CHEAPEST = 'POINTS_FREE_CHEAPEST'
DEFAULT_POINT_REWARD_PROMO_ID = 'POINT_REWARD'
DEFAULT_POINT_REWARD_PROMO_NAME = 'Points Reward'
DEFAULT_POINT_REWARD_PROMO_COST = 100

SPECIAL_RECIPE_SHOT_ID = 'SHOT'
SPECIAL_RECIPE_BESPOKE_ID = 'BESPOKE'
BESPOKE_FIXED_SALE_PRICE = Decimal('200000')
SPECIAL_RECIPE_CLASSIC_ID = 'CLASSIC'
CLASSIC_ALLOWED_SALE_PRICES = (
    Decimal('150000'),
    Decimal('180000')
)
SPECIAL_RECIPE_STANDALONE_INGREDIENT = 'STANDALONE_INGREDIENT'
SPECIAL_RECIPE_CUSTOM_ONE_TIME = 'CUSTOM_ONE_TIME'
SPECIAL_RECIPE_CLASSIC_OFF_MENU = 'CLASSIC_OFF_MENU'


finalization_lock = threading.Lock()
promocode_lock = threading.Lock()


def normalize_text(value):

    return str(value).strip().upper()


def money(value):

    return Decimal(
        str(value)
    ).quantize(
        MONEY_PLACES,
        rounding=ROUND_HALF_UP
    )


def money_output(value):

    value = money(value)

    if value == value.to_integral():

        return int(value)

    return float(value)


@synchronized(log_lock)
def write_log(action):

    timestamp = datetime.now().strftime(
        '%Y-%m-%d %H:%M:%S'
    )

    with open(
        log_file,
        'a',
        encoding='utf-8'
    ) as file:

        file.write(
            f'[{timestamp}] {action}\n'
        )

    # Keep server log current in the live backup too. Avoid recursive logging.
    if (
        backup_data_root is not None
        and active_data_root is not None
        and storage_mode == 'MAIN'
    ):
        try:
            backup_log = Path(backup_data_root) / 'NAU_LOG.txt'
            backup_log.parent.mkdir(parents=True, exist_ok=True)
            with open(
                backup_log,
                'a',
                encoding='utf-8'
            ) as backup_file:
                backup_file.write(
                    f'[{timestamp}] {action}\n'
                )
        except OSError:
            pass


def get_server_log_snapshot(
    after=None,
    tail=None
):

    if not log_file.exists():

        return {
            'lines':
                [],

            'cursor':
                0,

            'total_lines':
                0
        }

    with open(
        log_file,
        'r',
        encoding='utf-8',
        errors='replace'
    ) as file:

        lines = (
            file.read()
            .splitlines()
        )

    total_lines = len(
        lines
    )

    if after is not None:

        try:

            start_index = int(
                after
            )

        except Exception:

            raise ValueError(
                'Server log cursor must be an integer.'
            )

        if start_index < 0:

            start_index = 0

        if start_index > total_lines:

            start_index = total_lines

    elif tail is not None:

        try:

            tail_count = int(
                tail
            )

        except Exception:

            raise ValueError(
                'Server log tail must be an integer.'
            )

        if tail_count < 0:

            tail_count = 0

        if tail_count > 500:

            tail_count = 500

        start_index = max(
            0,
            total_lines - tail_count
        )

    else:

        start_index = total_lines

    return {
        'lines':
            lines[
                start_index:
            ],

        'cursor':
            total_lines,

        'total_lines':
            total_lines
    }


def write_sale(
    transaction_id,
    table,
    opened_at,
    paid_at,
    payment_method,
    drink_names,
    subtotal,
    promo,
    discount_amount,
    total
):

    table_names = {
        1: 'Bar 1',
        2: 'Bar 2',
        3: 'Bar 3',
        4: 'Bar 4',
        5: 'Sofa',
        6: 'Couple',
        7: 'Bartender',
        8: 'Owner'
    }

    try:

        table_number = int(
            table
        )

        table_display = table_names.get(
            table_number,
            str(table)
        )

    except Exception:

        table_display = str(
            table
        )

    drink_text = ' | '.join(
        drink_names
    )

    if isinstance(
        promo,
        dict
    ):

        promo_id = normalize_text(
            promo.get(
                'id',
                ''
            )
        )

        promo_name = str(
            promo.get(
                'name',
                ''
            )
        ).strip()

        promo_type = normalize_text(
            promo.get(
                'type',
                ''
            )
        )

        if (
            promo_type
            ==
            SPECIAL_PROMO_POINTS_FREE_CHEAPEST
        ):
            promo_value = (
                f'{int(promo.get("points_cost", 0) or 0)} POINTS'
            )

        else:
            promo_value = money_output(
                promo.get(
                    'value',
                    0
                )
            )

        promo_text = (
            f'PROMO={promo_id or "UNKNOWN"} | '
            f'PROMO_NAME={promo_name or "UNKNOWN"} | '
            f'PROMO_TYPE={promo_type or "UNKNOWN"} | '
            f'PROMO_VALUE={promo_value}'
        )

    else:

        promo_text = (
            'PROMO=NONE'
        )

    sale_line = (
        f"[{paid_at.strftime('%Y-%m-%d %H:%M')}] "
        f"TX={transaction_id} | "
        f"TABLE={table_display} | "
        f"OPENED={opened_at.strftime('%Y-%m-%d %H:%M')} | "
        f"PAYMENT={payment_method} | "
        f"{drink_text} | "
        f"SUBTOTAL={money_output(subtotal)} | "
        f"{promo_text} | "
        f"DISCOUNT={money_output(discount_amount)} | "
        f"TOTAL={money_output(total)}\n"
    )

    with open(
        sales_file,
        'a',
        encoding='utf-8'
    ) as file:

        file.write(
            sale_line
        )

        file.flush()

        os.fsync(
            file.fileno()
        )


def decimal_output(value):

    value = Decimal(
        str(value)
    )

    if value == value.to_integral():

        return int(
            value
        )

    return float(
        value
    )


def validate_payment_method(
    payment_method
):

    if not isinstance(
        payment_method,
        str
    ):

        raise ValueError(
            'Payment method must be text.'
        )


    normalized = (
        payment_method
        .strip()
        .upper()
        .replace(
            '-',
            '_'
        )
        .replace(
            ' ',
            '_'
        )
    )


    allowed = {
        'CASH',
        'BANK_TRANSFER',
        'INTERNAL'
    }


    if normalized not in allowed:

        raise ValueError(
            'Payment method must be CASH, BANK_TRANSFER or INTERNAL.'
        )


    return normalized


def validate_transaction_id(
    transaction_id
):

    if not isinstance(
        transaction_id,
        str
    ):

        raise ValueError(
            'Transaction ID must be text.'
        )

    transaction_id = (
        transaction_id
        .strip()
        .upper()
    )

    if not transaction_id:

        raise ValueError(
            'Transaction ID cannot be empty.'
        )

    if len(
        transaction_id
    ) > 128:

        raise ValueError(
            'Transaction ID is too long.'
        )

    if any(
        character in transaction_id
        for character in (
            '\r',
            '\n',
            '\t'
        )
    ):

        raise ValueError(
            'Transaction ID contains invalid characters.'
        )

    return transaction_id


def write_json_file_atomic(
    file_path,
    data
):

    file_path = Path(
        file_path
    )

    file_path.parent.mkdir(
        parents=True,
        exist_ok=True
    )

    temp_name = (
        f'.{file_path.name}.'
        f'{os.getpid()}.'
        f'{threading.get_ident()}.tmp'
    )

    temp_path = (
        file_path.parent /
        temp_name
    )

    try:

        with open(
            temp_path,
            'w',
            encoding='utf-8'
        ) as file:

            json.dump(
                data,
                file,
                indent=4,
                ensure_ascii=False
            )

            file.write(
                '\n'
            )

            file.flush()

            os.fsync(
                file.fileno()
            )

        os.replace(
            temp_path,
            file_path
        )

    except Exception:

        try:

            if temp_path.exists():

                temp_path.unlink()

        except Exception:

            pass

        raise



# ============================================================
# OPEN / UNPAID TABLE ORDER RECOVERY
#
# Fixed-table snapshots are intentionally outside DATABASE/HISTORY:
#
#   <NAU>/TEMPS/ORDER DATA/Bar 1.json
#   <NAU>/TEMPS/ORDER DATA/Bar 2.json
#   <NAU>/TEMPS/ORDER DATA/Bar 3.json
#   <NAU>/TEMPS/ORDER DATA/Bar 4.json
#   <NAU>/TEMPS/ORDER DATA/Sofa.json
#   <NAU>/TEMPS/ORDER DATA/Couple.json
#   <NAU>/TEMPS/ORDER DATA/Bartender.json
#   <NAU>/TEMPS/ORDER DATA/Owner.json
#
# They are still inside the NAU root, so the existing live MAIN/BACKUP mirror
# and whole-NAU Google backup naturally include them.
# ============================================================

OPEN_ORDER_TABLE_NAMES = (
    'Bar 1',
    'Bar 2',
    'Bar 3',
    'Bar 4',
    'Sofa',
    'Couple',
    'Bartender',
    'Owner',
)


INTERNAL_OPEN_ORDER_TABLE_NAMES = (
    'Bartender',
    'Owner',
)


def is_internal_open_order_table(
    table_name
):
    return (
        normalize_open_order_table_name(
            table_name
        )
        in
        INTERNAL_OPEN_ORDER_TABLE_NAMES
    )


def normalize_open_order_table_name(
    value
):
    aliases = {
        'BAR 1': 'Bar 1',
        'BAR 2': 'Bar 2',
        'BAR 3': 'Bar 3',
        'BAR 4': 'Bar 4',
        'SOFA': 'Sofa',
        'COUPLE': 'Couple',
        'BARTENDER': 'Bartender',
        'OWNER': 'Owner',
        '1': 'Bar 1',
        '2': 'Bar 2',
        '3': 'Bar 3',
        '4': 'Bar 4',
        '5': 'Sofa',
        '6': 'Couple',
        '7': 'Bartender',
        '8': 'Owner',
    }

    if isinstance(
        value,
        bool
    ):
        raise ValueError(
            'Invalid table name.'
        )

    if isinstance(
        value,
        int
    ):
        key = str(
            value
        )

    elif isinstance(
        value,
        float
    ):

        if not value.is_integer():
            raise ValueError(
                'Invalid table name.'
            )

        key = str(
            int(
                value
            )
        )

    else:
        key = str(
            value
            or
            ''
        ).strip().upper()

    resolved = aliases.get(
        key
    )

    if resolved is None:
        raise ValueError(
            'Unknown table. Expected one of: '
            +
            ', '.join(
                OPEN_ORDER_TABLE_NAMES
            )
        )

    return resolved


def normalize_open_order_revision(
    value
):
    if isinstance(
        value,
        bool
    ):
        return 0

    try:
        revision = int(
            value
        )

    except (
        TypeError,
        ValueError
    ):
        return 0

    if revision < 0:
        return 0

    return revision


def normalize_open_order_updated_at(
    value
):
    if value is None:
        return None

    value = str(
        value
    ).strip()

    return (
        value
        or
        None
    )


def open_order_updated_timestamp():
    return datetime.now().astimezone().isoformat(
        timespec='milliseconds'
    )


def empty_open_order_table_state(
    table_name,
    revision=0,
    updated_at=None
):
    table_name = normalize_open_order_table_name(
        table_name
    )

    return {
        'table':
            table_name,

        'isOpen':
            is_internal_open_order_table(
                table_name
            ),

        'openedAt':
            None,

        'transactionId':
            None,

        'promo':
            None,

        'customer':
            None,

        'note':
            '',

        'items':
            [],

        'revision':
            normalize_open_order_revision(
                revision
            ),

        'updatedAt':
            normalize_open_order_updated_at(
                updated_at
            )
    }


def normalize_open_order_table_state(
    table_name,
    raw_state
):
    table_name = normalize_open_order_table_name(
        table_name
    )

    if not isinstance(
        raw_state,
        dict
    ):
        return empty_open_order_table_state(
            table_name
        )

    revision = normalize_open_order_revision(
        raw_state.get(
            'revision'
        )
    )

    updated_at = normalize_open_order_updated_at(
        raw_state.get(
            'updatedAt'
        )
    )

    is_open = bool(
        raw_state.get(
            'isOpen'
        )
    )

    if not is_open:
        return empty_open_order_table_state(
            table_name,
            revision=revision,
            updated_at=updated_at
        )

    opened_at = raw_state.get(
        'openedAt'
    )

    if opened_at is not None:
        opened_at = str(
            opened_at
        ).strip() or None

    transaction_id = raw_state.get(
        'transactionId'
    )

    if transaction_id is not None:
        transaction_id = str(
            transaction_id
        ).strip() or None

    promo = raw_state.get(
        'promo'
    )

    if not isinstance(
        promo,
        dict
    ):
        promo = None

    customer = raw_state.get(
        'customer'
    )

    if not isinstance(
        customer,
        dict
    ):
        customer = None

    note = str(
        raw_state.get(
            'note',
            ''
        )
        or
        ''
    )

    note = note[
        :1000
    ]

    raw_items = raw_state.get(
        'items'
    )

    if not isinstance(
        raw_items,
        list
    ):
        raw_items = []

    items = []

    for raw_item in raw_items[
        :500
    ]:

        if not isinstance(
            raw_item,
            dict
        ):
            continue

        try:
            item = json.loads(
                json.dumps(
                    raw_item,
                    ensure_ascii=False
                )
            )

        except (
            TypeError,
            ValueError
        ):
            continue

        items.append(
            item
        )

    return {
        'table':
            table_name,

        'isOpen':
            True,

        'openedAt':
            opened_at,

        'transactionId':
            transaction_id,

        'promo':
            promo,

        'customer':
            customer,

        'note':
            note,

        'items':
            items,

        'revision':
            revision,

        'updatedAt':
            updated_at
    }


def open_order_state_content(
    state
):
    """
    Return only business/order fields.

    revision + updatedAt are synchronization metadata and must not make an
    otherwise identical table look changed.
    """
    return {
        'table':
            state.get(
                'table'
            ),

        'isOpen':
            bool(
                state.get(
                    'isOpen'
                )
            ),

        'openedAt':
            state.get(
                'openedAt'
            ),

        'transactionId':
            state.get(
                'transactionId'
            ),

        'promo':
            state.get(
                'promo'
            ),

        'customer':
            state.get(
                'customer'
            ),

        'note':
            state.get(
                'note',
                ''
            ),

        'items':
            state.get(
                'items',
                []
            )
    }


def open_order_states_match(
    first,
    second
):
    return (
        open_order_state_content(
            first
        )
        ==
        open_order_state_content(
            second
        )
    )


def open_order_table_file(
    table_name
):
    table_name = normalize_open_order_table_name(
        table_name
    )

    return (
        order_data_folder /
        f'{table_name}.json'
    )


def read_open_order_table_state(
    table_name
):
    table_name = normalize_open_order_table_name(
        table_name
    )

    file_path = open_order_table_file(
        table_name
    )

    if not file_path.is_file():
        return empty_open_order_table_state(
            table_name
        )

    raw_state = read_json_file(
        file_path
    )

    return normalize_open_order_table_state(
        table_name,
        raw_state
    )


@synchronized(order_data_lock)
def save_open_order_tables(
    raw_tables
):
    """
    Save all six table snapshots as ONE optimistic-concurrency transaction.

    Every changed table must carry the exact revision currently stored on the
    server. If even one changed table is stale, NONE of the tables are written.
    This prevents half-applied transfers and stale POS windows overwriting a
    newer order.

    Sending an older revision with IDENTICAL business content is treated as a
    harmless no-op and the current server revision is returned.
    """
    if not isinstance(
        raw_tables,
        dict
    ):
        raise ValueError(
            'Order-data payload needs a tables object.'
        )

    missing_tables = [
        table_name
        for table_name in OPEN_ORDER_TABLE_NAMES
        if table_name not in raw_tables
    ]

    if missing_tables:
        raise ValueError(
            'Order-data payload is missing table(s): '
            +
            ', '.join(
                missing_tables
            )
        )

    order_data_folder.mkdir(
        parents=True,
        exist_ok=True
    )

    current_tables = {}

    incoming_tables = {}

    conflicts = {}

    for table_name in OPEN_ORDER_TABLE_NAMES:

        current_state = read_open_order_table_state(
            table_name
        )

        incoming_state = normalize_open_order_table_state(
            table_name,
            raw_tables.get(
                table_name
            )
        )

        current_tables[
            table_name
        ] = current_state

        incoming_tables[
            table_name
        ] = incoming_state

        if open_order_states_match(
            current_state,
            incoming_state
        ):
            continue

        expected_revision = incoming_state[
            'revision'
        ]

        current_revision = current_state[
            'revision'
        ]

        if expected_revision != current_revision:

            conflicts[
                table_name
            ] = {
                'expected_revision':
                    expected_revision,

                'current_revision':
                    current_revision,

                'server_updated_at':
                    current_state.get(
                        'updatedAt'
                    )
            }

    # Request-level atomicity: if one changed table is stale, write NOTHING.
    if conflicts:

        return {
            'conflict':
                True,

            'tables':
                current_tables,

            'conflicts':
                conflicts,

            'changed_tables':
                []
        }

    saved = {}

    changed_tables = []

    timestamp = open_order_updated_timestamp()

    for table_name in OPEN_ORDER_TABLE_NAMES:

        current_state = current_tables[
            table_name
        ]

        incoming_state = incoming_tables[
            table_name
        ]

        if open_order_states_match(
            current_state,
            incoming_state
        ):

            saved[
                table_name
            ] = current_state

            continue

        incoming_state[
            'revision'
        ] = (
            current_state[
                'revision'
            ]
            +
            1
        )

        incoming_state[
            'updatedAt'
        ] = timestamp

        write_json_file_atomic(
            open_order_table_file(
                table_name
            ),
            incoming_state
        )

        saved[
            table_name
        ] = incoming_state

        changed_tables.append(
            table_name
        )

    return {
        'conflict':
            False,

        'tables':
            saved,

        'conflicts':
            {},

        'changed_tables':
            changed_tables
    }


@synchronized(order_data_lock)
def initialize_open_order_table_files():
    """
    Guarantee that every fixed table always has a recovery JSON.

    Existing files are NEVER reset here. Older files without revision metadata
    remain valid and are interpreted as revision 0 until their next change.
    """
    global order_data_files_created_on_startup

    order_data_folder.mkdir(
        parents=True,
        exist_ok=True
    )

    created = []

    for table_name in OPEN_ORDER_TABLE_NAMES:

        file_path = open_order_table_file(
            table_name
        )

        if file_path.exists():
            continue

        write_json_file_atomic(
            file_path,
            empty_open_order_table_state(
                table_name
            )
        )

        created.append(
            file_path.name
        )

    order_data_files_created_on_startup = (
        created
    )

    return created


@synchronized(order_data_lock)
def load_open_order_tables():
    order_data_folder.mkdir(
        parents=True,
        exist_ok=True
    )

    tables = {}

    existing_files = []

    errors = {}

    for table_name in OPEN_ORDER_TABLE_NAMES:

        file_path = open_order_table_file(
            table_name
        )

        if not file_path.is_file():

            tables[
                table_name
            ] = empty_open_order_table_state(
                table_name
            )

            continue

        existing_files.append(
            file_path.name
        )

        try:
            tables[
                table_name
            ] = read_open_order_table_state(
                table_name
            )

        except Exception as error:

            tables[
                table_name
            ] = empty_open_order_table_state(
                table_name
            )

            errors[
                table_name
            ] = str(
                error
            )

    return {
        'tables':
            tables,

        'existing_files':
            existing_files,

        'created_on_startup':
            list(
                order_data_files_created_on_startup
            ),

        'saved_table_count':
            len(
                existing_files
            ),

        'errors':
            errors,

        'relative_folder':
            'TEMPS/ORDER DATA'
    }


@synchronized(order_data_lock)
def reset_open_order_table(
    table_name
):
    """
    Reset a persisted table without ever moving its revision backwards.

    Normal customer tables become closed. Bartender / Owner reset to an empty
    but still-open state because those internal-use tables are permanent.
    """
    table_name = normalize_open_order_table_name(
        table_name
    )

    order_data_folder.mkdir(
        parents=True,
        exist_ok=True
    )

    current_state = read_open_order_table_state(
        table_name
    )

    state = empty_open_order_table_state(
        table_name,
        revision=(
            current_state[
                'revision'
            ]
            +
            1
        ),
        updated_at=open_order_updated_timestamp()
    )

    write_json_file_atomic(
        open_order_table_file(
            table_name
        ),
        state
    )

    return state



def get_pending_sale_file(
    transaction_id
):

    transaction_id = (
        validate_transaction_id(
            transaction_id
        )
    )

    digest = hashlib.sha256(
        transaction_id.encode(
            'utf-8'
        )
    ).hexdigest()

    return (
        pending_sales_folder /
        f'{digest}.json'
    )


def get_pending_adjustment_file(
    transaction_id,
    action
):

    transaction_id = (
        validate_transaction_id(
            transaction_id
        )
    )

    action = normalize_text(
        action
    )

    if action not in {
        'VOID'
    }:

        raise ValueError(
            'Invalid pending sale adjustment action.'
        )

    digest = hashlib.sha256(
        (
            transaction_id
            +
            '|'
            +
            action
        ).encode(
            'utf-8'
        )
    ).hexdigest()

    return (
        pending_adjustments_folder /
        f'{digest}.json'
    )



def find_sale_by_transaction_id(
    transaction_id
):

    transaction_id = (
        validate_transaction_id(
            transaction_id
        )
    )

    if not sales_history_folder.exists():

        return None

    for file_path in sorted(
        sales_history_folder.glob(
            '*.json'
        )
    ):

        try:

            data = read_json_file(
                file_path
            )

        except Exception as error:

            raise ValueError(
                f'Sales history file could not be read: '
                f'{file_path.name}: {error}'
            )

        sales = data.get(
            'sales',
            []
        )

        if not isinstance(
            sales,
            list
        ):

            raise ValueError(
                f'Invalid sales history file: '
                f'{file_path.name}'
            )

        for sale in sales:

            if not isinstance(
                sale,
                dict
            ):

                continue

            stored_id = str(
                sale.get(
                    'transaction_id',
                    ''
                )
            ).strip().upper()

            if stored_id == transaction_id:

                return {
                    'file':
                        file_path,

                    'history':
                        data,

                    'sale':
                        sale
                }

    return None


def validate_sales_history_date(
    date_text
):

    if date_text is None:

        return None

    date_text = str(
        date_text
    ).strip()

    if not date_text:

        return None

    try:

        parsed_date = datetime.strptime(
            date_text,
            '%Y-%m-%d'
        )

    except Exception:

        raise ValueError(
            'Sales history date must use YYYY-MM-DD format.'
        )

    normalized_date = parsed_date.strftime(
        '%Y-%m-%d'
    )

    if normalized_date != date_text:

        raise ValueError(
            'Sales history date must use YYYY-MM-DD format.'
        )

    return normalized_date


def get_sales_history(
    date_filter=None
):

    date_filter = (
        validate_sales_history_date(
            date_filter
        )
    )

    if not sales_history_folder.exists():

        return []

    if date_filter is None:

        history_files = sorted(
            sales_history_folder.glob(
                '*.json'
            )
        )

    else:

        history_files = sorted(
            sales_history_folder.glob(
                f'{date_filter}_*.json'
            )
        )

    sales = []

    for file_path in history_files:

        try:

            history_data = read_json_file(
                file_path
            )

        except Exception as error:

            raise ValueError(
                f'Sales history file could not be read: '
                f'{file_path.name}: {error}'
            )

        if not isinstance(
            history_data,
            dict
        ):

            raise ValueError(
                f'Invalid sales history file: '
                f'{file_path.name}'
            )

        file_date = str(
            history_data.get(
                'date',
                ''
            )
        ).strip()

        if (
            date_filter is not None
            and
            file_date != date_filter
        ):

            raise ValueError(
                f'Sales history date mismatch in '
                f'{file_path.name}.'
            )

        file_sales = history_data.get(
            'sales',
            []
        )

        if not isinstance(
            file_sales,
            list
        ):

            raise ValueError(
                f'Invalid sales history file: '
                f'{file_path.name}'
            )

        for sale in file_sales:

            if not isinstance(
                sale,
                dict
            ):

                raise ValueError(
                    f'Invalid sale record in '
                    f'{file_path.name}.'
                )

            sales.append(
                sale
            )

    sales.sort(
        key=lambda sale:
            str(
                sale.get(
                    'paid_at',
                    ''
                )
            ),
        reverse=True
    )

    return sales


def google_finance_credentials(interactive=False):
    """Use a Desktop OAuth login for the account that will own the spreadsheet."""
    try:
        from google.auth.transport.requests import Request
        from google.oauth2.credentials import Credentials
        from google_auth_oauthlib.flow import InstalledAppFlow
    except ImportError as error:
        raise RuntimeError(
            'Google libraries missing. Install google-api-python-client, '
            'google-auth-httplib2 and google-auth-oauthlib, then rebuild NAU_SERVER.exe.'
        ) from error

    scopes = ['https://www.googleapis.com/auth/drive']
    credentials = None
    if google_token_file.exists():
        credentials = Credentials.from_authorized_user_file(
            str(google_token_file), scopes=scopes
        )
    if credentials and credentials.expired and credentials.refresh_token:
        try:
            credentials.refresh(Request())
        except Exception:
            if not interactive:
                raise RuntimeError(
                    'Google login expired. Press Sync to sheet on the server PC '
                    'and complete Google sign-in again.'
                )
            credentials = None

    if not credentials or not credentials.valid:
        if not interactive:
            raise RuntimeError(
                'Google sign-in needed. Press Sync to sheet on the server PC '
                'to sign in with the Google account that owns the finance folder.'
            )
        client_file = Path(google_finance_settings['client_file'])
        flow = InstalledAppFlow.from_client_secrets_file(str(client_file), scopes)
        credentials = flow.run_local_server(port=0, open_browser=True)

    settings_folder.mkdir(parents=True, exist_ok=True)
    temporary = google_token_file.with_suffix('.json.tmp')
    try:
        temporary.write_text(credentials.to_json(), encoding='utf-8')
        os.replace(temporary, google_token_file)
    finally:
        temporary.unlink(missing_ok=True)
    return credentials


def finance_number(value):
    """Match Finance's Number(value || 0), treating invalid amounts as zero."""
    try:
        number = Decimal(str(value or 0))
        return number if number.is_finite() else Decimal(0)
    except (InvalidOperation, ValueError, TypeError):
        return Decimal(0)


COST_HISTORY_VERSION = 1

COST_CATEGORY_CUSTOMER = 'CUSTOMER_SALE'
COST_CATEGORY_BARTENDER = 'BARTENDER_FREE'
COST_CATEGORY_OWNER = 'OWNER_CONSUMPTION'


def cost_history_category_for_sale(
    sale
):
    if (
        str(
            sale.get(
                'sale_kind',
                ''
            )
        )
        .strip()
        .upper()
        ==
        'INTERNAL_CONSUMPTION'
    ):
        account = str(
            sale.get(
                'internal_account'
            )
            or
            sale.get(
                'table'
            )
            or
            ''
        ).strip().upper()

        if account == 'BARTENDER':
            return COST_CATEGORY_BARTENDER

        if account == 'OWNER':
            return COST_CATEGORY_OWNER

    return COST_CATEGORY_CUSTOMER


def build_cost_history_entry(
    sale
):
    if not isinstance(
        sale,
        dict
    ):
        raise ValueError(
            'Invalid sale record for cost history.'
        )

    transaction_id = str(
        sale.get(
            'transaction_id'
        )
        or
        ''
    ).strip()

    if not transaction_id:
        raise ValueError(
            'Sale is missing a transaction ID.'
        )

    paid_at = str(
        sale.get(
            'paid_at'
        )
        or
        ''
    ).strip()

    business_date = str(
        sale.get(
            'business_date'
        )
        or
        ''
    ).strip()

    if not business_date:
        try:
            business_date = (
                datetime.fromisoformat(
                    paid_at
                )
                .date()
                .isoformat()
            )
        except Exception:
            business_date = ''

    category = (
        cost_history_category_for_sale(
            sale
        )
    )

    voided = (
        sale.get(
            'voided'
        )
        is True
    )

    refunded = (
        sale.get(
            'refunded'
        )
        is True
    )

    raw_ingredient_cost = money(
        finance_number(
            sale.get(
                'ingredient_cost'
            )
        )
    )

    effective_ingredient_cost = (
        Decimal(
            '0'
        )
        if voided
        else raw_ingredient_cost
    )

    effective_revenue = (
        Decimal(
            '0'
        )
        if voided
        else money(
            finance_number(
                sale.get(
                    'total'
                )
            )
        )
    )

    retail_value = money(
        finance_number(
            (
                sale.get(
                    'internal_retail_value'
                )
                if category
                in (
                    COST_CATEGORY_BARTENDER,
                    COST_CATEGORY_OWNER,
                )
                else sale.get(
                    'subtotal',
                    sale.get(
                        'original_total',
                        sale.get(
                            'total',
                            0
                        )
                    )
                )
            )
        )
    )

    profit_after_cost = money(
        effective_revenue
        -
        effective_ingredient_cost
    )

    return {
        'transaction_id':
            transaction_id,

        'paid_at':
            paid_at,

        'business_date':
            business_date,

        'category':
            category,

        'table':
            str(
                sale.get(
                    'table'
                )
                or
                ''
            ),

        'internal_account':
            (
                str(
                    sale.get(
                        'internal_account'
                    )
                    or
                    ''
                ).strip()
                or
                None
            ),

        'ingredient_cost':
            money_output(
                effective_ingredient_cost
            ),

        'original_ingredient_cost':
            money_output(
                raw_ingredient_cost
            ),

        'revenue':
            money_output(
                effective_revenue
            ),

        'retail_value':
            money_output(
                retail_value
            ),

        'profit_after_cost':
            money_output(
                profit_after_cost
            ),

        'refunded':
            refunded,

        'voided':
            voided,

        'drink_names':
            [
                str(
                    value
                )
                for value in (
                    sale.get(
                        'drink_names'
                    )
                    or
                    []
                )
            ]
    }


def rebuild_cost_history():
    with cost_history_lock:
        cost_history_folder.mkdir(
            parents=True,
            exist_ok=True
        )

        entries = []

        for sale in get_sales_history():
            try:
                entries.append(
                    build_cost_history_entry(
                        sale
                    )
                )
            except Exception as error:
                try:
                    write_log(
                        'COST HISTORY ENTRY SKIPPED | '
                        f'TX={sale.get("transaction_id", "")} | '
                        f'ERROR={error}'
                    )
                except Exception:
                    pass

        entries.sort(
            key=lambda entry:
                (
                    entry.get(
                        'paid_at'
                    )
                    or
                    ''
                ),
            reverse=True
        )

        store = {
            'version':
                COST_HISTORY_VERSION,

            'updated_at':
                datetime.now()
                .astimezone()
                .isoformat(
                    timespec='seconds'
                ),

            'entries':
                entries
        }

        write_json_file_atomic(
            cost_history_file,
            store
        )

        return store


def refresh_cost_history_best_effort(
    context=''
):
    try:
        return rebuild_cost_history()
    except Exception as error:
        try:
            write_log(
                'COST HISTORY REFRESH FAILED | '
                f'CONTEXT={str(context or "").strip() or "UNKNOWN"} | '
                f'ERROR={error}'
            )
        except Exception:
            pass

        return None


def normalize_cost_history_period(
    value
):
    normalized = str(
        value
        or
        'DAY'
    ).strip().upper()

    if normalized not in (
        'DAY',
        'WEEK',
        'MONTH',
    ):
        raise ValueError(
            'Cost history period must be DAY, WEEK or MONTH.'
        )

    return normalized


def normalize_cost_history_anchor_date(
    value
):
    text = str(
        value
        or
        ''
    ).strip()

    if not text:
        return date.today()

    try:
        parsed = datetime.strptime(
            text,
            '%Y-%m-%d'
        ).date()
    except Exception as error:
        raise ValueError(
            'Cost history date must use YYYY-MM-DD.'
        ) from error

    return parsed


def cost_history_period_bounds(
    period,
    anchor_date
):
    period = normalize_cost_history_period(
        period
    )

    anchor = normalize_cost_history_anchor_date(
        anchor_date
    )

    if period == 'DAY':
        start = anchor
        end = anchor

    elif period == 'WEEK':
        start = (
            anchor
            -
            timedelta(
                days=
                    anchor.weekday()
            )
        )

        end = (
            start
            +
            timedelta(
                days=6
            )
        )

    else:
        start = anchor.replace(
            day=1
        )

        end = date(
            start.year,
            start.month,
            calendar.monthrange(
                start.year,
                start.month
            )[1]
        )

    return period, anchor, start, end


def summarize_cost_history(
    period='DAY',
    anchor_date=None
):
    (
        normalized_period,
        anchor,
        start,
        end
    ) = cost_history_period_bounds(
        period,
        anchor_date
    )

    store = rebuild_cost_history()

    filtered_entries = []

    for entry in store.get(
        'entries',
        []
    ):
        try:
            entry_date = datetime.strptime(
                str(
                    entry.get(
                        'business_date'
                    )
                    or
                    ''
                ),
                '%Y-%m-%d'
            ).date()
        except Exception:
            continue

        if (
            entry_date < start
            or
            entry_date > end
        ):
            continue

        filtered_entries.append(
            entry
        )

    total_consumed_cost = Decimal(
        '0'
    )

    customer_cost = Decimal(
        '0'
    )

    bartender_cost = Decimal(
        '0'
    )

    owner_cost = Decimal(
        '0'
    )

    customer_revenue = Decimal(
        '0'
    )

    bartender_retail_value = Decimal(
        '0'
    )

    owner_retail_value = Decimal(
        '0'
    )

    customer_count = 0
    bartender_count = 0
    owner_count = 0
    refunded_count = 0
    voided_count = 0

    daily = {}

    for entry in filtered_entries:
        category = entry.get(
            'category'
        )

        ingredient_cost = money(
            finance_number(
                entry.get(
                    'ingredient_cost'
                )
            )
        )

        revenue = money(
            finance_number(
                entry.get(
                    'revenue'
                )
            )
        )

        retail_value = money(
            finance_number(
                entry.get(
                    'retail_value'
                )
            )
        )

        if entry.get(
            'voided'
        ) is True:
            voided_count += 1

        if entry.get(
            'refunded'
        ) is True:
            refunded_count += 1

        total_consumed_cost += (
            ingredient_cost
        )

        if category == COST_CATEGORY_BARTENDER:
            bartender_cost += (
                ingredient_cost
            )

            bartender_retail_value += (
                retail_value
            )

            if (
                entry.get(
                    'voided'
                )
                is not True
            ):
                bartender_count += 1

        elif category == COST_CATEGORY_OWNER:
            owner_cost += (
                ingredient_cost
            )

            owner_retail_value += (
                retail_value
            )

            if (
                entry.get(
                    'voided'
                )
                is not True
            ):
                owner_count += 1

        else:
            customer_cost += (
                ingredient_cost
            )

            customer_revenue += (
                revenue
            )

            if (
                entry.get(
                    'voided'
                )
                is not True
            ):
                customer_count += 1

        day_key = str(
            entry.get(
                'business_date'
            )
            or
            ''
        )

        if day_key:
            day_summary = daily.setdefault(
                day_key,
                {
                    'date':
                        day_key,

                    'total_consumed_cost':
                        Decimal(
                            '0'
                        ),

                    'customer_cost':
                        Decimal(
                            '0'
                        ),

                    'bartender_cost':
                        Decimal(
                            '0'
                        ),

                    'owner_cost':
                        Decimal(
                            '0'
                        ),

                    'customer_revenue':
                        Decimal(
                            '0'
                        )
                }
            )

            day_summary[
                'total_consumed_cost'
            ] += ingredient_cost

            if category == COST_CATEGORY_BARTENDER:
                day_summary[
                    'bartender_cost'
                ] += ingredient_cost

            elif category == COST_CATEGORY_OWNER:
                day_summary[
                    'owner_cost'
                ] += ingredient_cost

            else:
                day_summary[
                    'customer_cost'
                ] += ingredient_cost

                day_summary[
                    'customer_revenue'
                ] += revenue

    total_consumed_cost = money(
        total_consumed_cost
    )

    customer_cost = money(
        customer_cost
    )

    bartender_cost = money(
        bartender_cost
    )

    owner_cost = money(
        owner_cost
    )

    customer_revenue = money(
        customer_revenue
    )

    internal_cost = money(
        bartender_cost
        +
        owner_cost
    )

    customer_profit_before_internal = money(
        customer_revenue
        -
        customer_cost
    )

    final_profit = money(
        customer_revenue
        -
        total_consumed_cost
    )

    daily_rows = []

    for day_key in sorted(
        daily.keys()
    ):
        row = daily[
            day_key
        ]

        row_total_cost = money(
            row[
                'total_consumed_cost'
            ]
        )

        row_revenue = money(
            row[
                'customer_revenue'
            ]
        )

        daily_rows.append(
            {
                'date':
                    row[
                        'date'
                    ],

                'total_consumed_cost':
                    money_output(
                        row_total_cost
                    ),

                'customer_cost':
                    money_output(
                        money(
                            row[
                                'customer_cost'
                            ]
                        )
                    ),

                'bartender_cost':
                    money_output(
                        money(
                            row[
                                'bartender_cost'
                            ]
                        )
                    ),

                'owner_cost':
                    money_output(
                        money(
                            row[
                                'owner_cost'
                            ]
                        )
                    ),

                'customer_revenue':
                    money_output(
                        row_revenue
                    ),

                'final_profit':
                    money_output(
                        money(
                            row_revenue
                            -
                            row_total_cost
                        )
                    )
            }
        )

    return {
        'period':
            normalized_period,

        'anchor_date':
            anchor.isoformat(),

        'start_date':
            start.isoformat(),

        'end_date':
            end.isoformat(),

        'entry_count':
            len(
                filtered_entries
            ),

        'summary':
            {
                'total_consumed_cost':
                    money_output(
                        total_consumed_cost
                    ),

                'customer_cost':
                    money_output(
                        customer_cost
                    ),

                'bartender_cost':
                    money_output(
                        bartender_cost
                    ),

                'owner_cost':
                    money_output(
                        owner_cost
                    ),

                'internal_cost':
                    money_output(
                        internal_cost
                    ),

                'customer_revenue':
                    money_output(
                        customer_revenue
                    ),

                'customer_profit_before_internal':
                    money_output(
                        customer_profit_before_internal
                    ),

                'final_profit':
                    money_output(
                        final_profit
                    ),

                'bartender_retail_value':
                    money_output(
                        money(
                            bartender_retail_value
                        )
                    ),

                'owner_retail_value':
                    money_output(
                        money(
                            owner_retail_value
                        )
                    ),

                'customer_count':
                    customer_count,

                'bartender_count':
                    bartender_count,

                'owner_count':
                    owner_count,

                'refunded_count':
                    refunded_count,

                'voided_count':
                    voided_count
            },

        'daily':
            daily_rows,

        'entries':
            filtered_entries
    }



def finance_daily_totals(sales, through):
    """
    Build the Google Finance daily totals.

    Columns are split so the sheet can show exactly where ingredient cost went:
    customer drinks versus internal Bartender/Owner consumption.

    Void semantics match Cost History:
    - VOIDED: inventory was restored -> 0 effective cost / 0 revenue
    - REFUNDED: ingredients were still consumed -> cost remains / revenue is 0
    - INTERNAL: revenue is 0, cost is grouped under internal used cost
    """
    totals = {}

    for sale in sales:
        if not isinstance(sale, dict):
            continue

        try:
            cost_entry = build_cost_history_entry(
                sale
            )
        except Exception:
            continue

        try:
            paid_day = datetime.strptime(
                str(
                    cost_entry.get(
                        'business_date'
                    )
                    or
                    ''
                ),
                '%Y-%m-%d'
            ).date()
        except ValueError:
            try:
                paid_day = datetime.fromisoformat(
                    str(
                        sale.get(
                            'paid_at',
                            ''
                        )
                    )
                ).date()
            except ValueError:
                continue

        if paid_day > through:
            continue

        amounts = totals.setdefault(
            paid_day,
            {
                'total_cost':
                    Decimal(
                        '0'
                    ),

                'internal_cost':
                    Decimal(
                        '0'
                    ),

                'customer_cost':
                    Decimal(
                        '0'
                    ),

                'revenue':
                    Decimal(
                        '0'
                    )
            }
        )

        ingredient_cost = finance_number(
            cost_entry.get(
                'ingredient_cost'
            )
        )

        revenue = finance_number(
            cost_entry.get(
                'revenue'
            )
        )

        category = str(
            cost_entry.get(
                'category'
            )
            or
            ''
        ).strip().upper()

        amounts[
            'total_cost'
        ] += ingredient_cost

        amounts[
            'revenue'
        ] += revenue

        if category in (
            COST_CATEGORY_BARTENDER,
            COST_CATEGORY_OWNER,
        ):
            amounts[
                'internal_cost'
            ] += ingredient_cost

        else:
            amounts[
                'customer_cost'
            ] += ingredient_cost

    return totals


def finance_sheet_whole_vnd(
    value
):
    """
    Google Finance sheet display value in whole VND.

    Intentionally DROP the fractional part instead of rounding it:
        7500231.8 -> 7500231
    """
    try:
        return int(
            finance_number(
                value
            )
        )
    except Exception:
        return 0


def finance_month_values(year, month, totals, through):
    """
    One stable row per calendar day. Rewrites never append duplicate days.

    Google Sheet columns:
    Day | Total cost spent | Internal used cost |
    Customer used cost | Revenue | Profit
    """
    values = [[
        'Day',
        'Total cost spent',
        'Internal used cost',
        'Customer used cost',
        'Revenue',
        'Profit'
    ]]

    for number in range(
        1,
        calendar.monthrange(
            year,
            month
        )[1] + 1
    ):
        day = date(
            year,
            month,
            number
        )

        row = [
            day.isoformat()
        ]

        if day <= through:
            amounts = totals.get(
                day,
                {
                    'total_cost':
                        Decimal(
                            '0'
                        ),

                    'internal_cost':
                        Decimal(
                            '0'
                        ),

                    'customer_cost':
                        Decimal(
                            '0'
                        ),

                    'revenue':
                        Decimal(
                            '0'
                        )
                }
            )

            total_cost = money(
                amounts[
                    'total_cost'
                ]
            )

            internal_cost = money(
                amounts[
                    'internal_cost'
                ]
            )

            customer_cost = money(
                amounts[
                    'customer_cost'
                ]
            )

            revenue = money(
                amounts[
                    'revenue'
                ]
            )

            profit = money(
                revenue
                -
                total_cost
            )

            row.extend(
                (
                    finance_sheet_whole_vnd(
                        total_cost
                    ),

                    finance_sheet_whole_vnd(
                        internal_cost
                    ),

                    finance_sheet_whole_vnd(
                        customer_cost
                    ),

                    finance_sheet_whole_vnd(
                        revenue
                    ),

                    finance_sheet_whole_vnd(
                        profit
                    )
                )
            )

        else:
            row.extend(
                (
                    '',
                    '',
                    '',
                    '',
                    ''
                )
            )

        values.append(
            row
        )

    return values


def google_find_or_create(drive, folder_id, title, mime_type):
    escaped = title.replace('\\', '\\\\').replace("'", "\\'")
    parent = "'root'" if folder_id is None else "'{}'".format(folder_id)
    query = (f"name = '{escaped}' and mimeType = '{mime_type}' and "
             f"{parent} in parents and trashed = false")
    matches = drive.files().list(
        q=query, fields='nextPageToken,files(id,name)', pageSize=100
    ).execute().get('files', [])
    if matches:
        return matches[0]['id'], False
    metadata = {'name': title, 'mimeType': mime_type}
    if folder_id is not None:
        metadata['parents'] = [folder_id]
    created = drive.files().create(body=metadata, fields='id').execute()
    return created['id'], True


def test_google_finance_connection():
    """Check Google auth, Drive and an existing Sheet without changing either."""
    if not google_finance_settings or not google_finance_settings.get('enabled'):
        raise RuntimeError('Google Finance is not configured on this server.')
    if not google_finance_lock.acquire(blocking=False):
        raise RuntimeError('A Google Finance sync or connection test is running.')
    try:
        try:
            from googleapiclient.discovery import build
        except ImportError as error:
            raise RuntimeError('Google libraries are missing from this server.') from error

        credentials = google_finance_credentials(interactive=True)
        drive = build('drive', 'v3', credentials=credentials, cache_discovery=False)
        folders = drive.files().list(
            q="name = 'FINANCE' and mimeType = "
              "'application/vnd.google-apps.folder' and 'root' in parents "
              "and trashed = false",
            fields='files(id,name)', pageSize=100
        ).execute().get('files', [])
        if not folders:
            return {
                'drive_connected': True,
                'sheets_checked': False,
                'message': 'Drive connected. Sync Finance once to create a '
                           'spreadsheet, then test Google Sheets access.'
            }

        spreadsheet = None
        for folder in folders:
            reports = drive.files().list(
                q="mimeType = 'application/vnd.google-apps.spreadsheet' "
                  f"and '{folder['id']}' in parents and trashed = false",
                fields='files(id,name)', pageSize=100
            ).execute().get('files', [])
            if reports:
                spreadsheet = max(reports, key=lambda item: item['name'])
                break
        if spreadsheet is None:
            return {
                'drive_connected': True,
                'sheets_checked': False,
                'message': 'Drive connected. No Finance spreadsheet yet; '
                           'sync Finance once, then test again.'
            }

        sheets = build('sheets', 'v4', credentials=credentials,
                       cache_discovery=False).spreadsheets()
        info = sheets.get(
            spreadsheetId=spreadsheet['id'],
            fields='properties(title),sheets(properties(title))'
        ).execute()
        months = {item['properties']['title'] for item in info.get('sheets', [])}
        missing = set(calendar.month_name[1:]) - months
        if missing:
            raise RuntimeError(
                'Google Sheets connected, but this finance report is missing '
                'month tabs: ' + ', '.join(sorted(missing))
            )
        return {
            'drive_connected': True,
            'sheets_checked': True,
            'spreadsheet': info.get('properties', {}).get('title',
                                                         spreadsheet['name']),
            'month_tabs': len(months),
            'message': 'Google Drive and Google Sheets connected; 12 month '
                       'tabs are readable. No data was changed.'
        }
    finally:
        google_finance_lock.release()


def get_google_finance_sheet_link():
    """Return the existing revenue spreadsheet URL without changing Sheet data."""
    if not google_finance_settings or not google_finance_settings.get('enabled'):
        raise RuntimeError('Google Finance is not configured on this server.')

    if not google_finance_lock.acquire(blocking=False):
        raise RuntimeError('A Google Finance sync or connection test is running.')

    try:
        try:
            from googleapiclient.discovery import build
        except ImportError as error:
            raise RuntimeError('Google libraries are missing from this server.') from error

        credentials = google_finance_credentials(interactive=False)
        drive = build(
            'drive',
            'v3',
            credentials=credentials,
            cache_discovery=False
        )

        folders = drive.files().list(
            q="name = 'FINANCE' and mimeType = "
              "'application/vnd.google-apps.folder' and 'root' in parents "
              "and trashed = false",
            fields='files(id,name)',
            pageSize=100
        ).execute().get('files', [])

        links = []

        for folder in folders:
            reports = drive.files().list(
                q="mimeType = 'application/vnd.google-apps.spreadsheet' "
                  f"and '{folder['id']}' in parents and trashed = false",
                fields='files(id,name,modifiedTime)',
                pageSize=100
            ).execute().get('files', [])

            for report in reports:
                name = str(report.get('name', '')).strip()
                match = re.fullmatch(r'([0-9]{4}) revenue', name, re.IGNORECASE)

                if not match:
                    continue

                year = int(match.group(1))
                spreadsheet_id = report['id']

                links.append({
                    'year': year,
                    'name': name,
                    'modified_time': report.get('modifiedTime'),
                    'url': f'https://docs.google.com/spreadsheets/d/{spreadsheet_id}/edit'
                })

        if not links:
            raise RuntimeError(
                'No revenue Google Sheet exists yet. Open Finance and sync to sheet once.'
            )

        links.sort(
            key=lambda item: (
                item['year'],
                item.get('modified_time') or ''
            ),
            reverse=True
        )

        current_year = date.today().year
        selected = next(
            (item for item in links if item['year'] == current_year),
            links[0]
        )

        return {
            'current_year': current_year,
            'selected': selected,
            'spreadsheets': links
        }

    finally:
        google_finance_lock.release()


def google_ensure_month_tabs(sheets, spreadsheet_id, newly_created):
    info = sheets.get(
        spreadsheetId=spreadsheet_id,
        fields='sheets(properties(sheetId,title,gridProperties(frozenRowCount)),bandedRanges)'
    ).execute()
    present = {sheet['properties']['title']: sheet['properties']
               for sheet in info.get('sheets', [])}
    months = list(calendar.month_name)[1:]
    requests = [{'addSheet': {'properties': {
        'title': month, 'gridProperties': {'frozenRowCount': 1}
    }}}
                for month in months if month not in present]
    requests.extend({
        'updateSheetProperties': {
            'properties': {
                'sheetId': present[month]['sheetId'],
                'gridProperties': {'frozenRowCount': 1}
            },
            'fields': 'gridProperties.frozenRowCount'
        }
    } for month in months if month in present and
        present[month].get('gridProperties', {}).get('frozenRowCount') != 1)
    if newly_created and 'Sheet1' in present:
        requests.append({'deleteSheet': {'sheetId': present['Sheet1']['sheetId']}})
    if requests:
        sheets.batchUpdate(
            spreadsheetId=spreadsheet_id, body={'requests': requests}
        ).execute()
        if any('addSheet' in request for request in requests):
            info = sheets.get(
                spreadsheetId=spreadsheet_id,
                fields='sheets(properties(sheetId,title),bandedRanges)'
            ).execute()

    # Match the Finance sheet's header and alternating row colors in every
    # monthly tab. A banded range also covers days not yet written by a sync.
    orange = {'red': 244 / 255, 'green': 101 / 255, 'blue': 36 / 255}
    peach = {'red': 1, 'green': 230 / 255, 'blue': 221 / 255}
    white = {'red': 1, 'green': 1, 'blue': 1}
    formatting = []
    for sheet in info.get('sheets', []):
        properties = sheet['properties']
        if properties['title'] not in months:
            continue
        sheet_id = properties['sheetId']
        wanted = {
            'range': {'sheetId': sheet_id, 'startRowIndex': 0,
                      'endRowIndex': 32, 'startColumnIndex': 0,
                      'endColumnIndex': 6},
            'rowProperties': {'headerColor': orange, 'firstBandColor': white,
                              'secondBandColor': peach}
        }
        overlapping = []
        for band in sheet.get('bandedRanges', []):
            area = band.get('range', {})
            if (area.get('startRowIndex', 0) < 32 and
                    area.get('endRowIndex', 32) > 0 and
                    area.get('startColumnIndex', 0) < 6 and
                    area.get('endColumnIndex', 6) > 0):
                overlapping.append(band)
        if overlapping:
            first = overlapping[0]
            if (first.get('range') != wanted['range'] or
                    first.get('rowProperties') != wanted['rowProperties'] or
                    first.get('columnProperties')):
                formatting.append({'updateBanding': {
                    'bandedRange': {'bandedRangeId': first['bandedRangeId'],
                                    **wanted},
                    'fields': 'range,rowProperties,columnProperties'
                }})
            for extra in overlapping[1:]:
                formatting.append({'deleteBanding': {
                    'bandedRangeId': extra['bandedRangeId']
                }})
        else:
            formatting.append({'addBanding': {'bandedRange': wanted}})
    if formatting:
        sheets.batchUpdate(
            spreadsheetId=spreadsheet_id, body={'requests': formatting}
        ).execute()


def google_format_finance_month_tabs(
    sheets,
    spreadsheet_id,
    year
):
    """
    Apply display-only formatting after monthly values have been written.

    Keeps the existing header/banding colors intact while:
    - auto-sizing columns A:F to fit their contents/header text
    - formatting B:F as comma-separated VND values

    Examples:
        100000       -> 100,000 VND
        2507768.2    -> 2,507,768.2 VND
    """
    info = sheets.get(
        spreadsheetId=
            spreadsheet_id,

        fields=
            'sheets(properties(sheetId,title))'
    ).execute()

    months = set(
        list(
            calendar.month_name
        )[1:]
    )

    requests = []

    for sheet in info.get(
        'sheets',
        []
    ):
        properties = sheet.get(
            'properties',
            {}
        )

        title = properties.get(
            'title'
        )

        if title not in months:
            continue

        sheet_id = properties[
            'sheetId'
        ]

        month_number = list(
            calendar.month_name
        ).index(
            title
        )

        month_day_count = calendar.monthrange(
            year,
            month_number
        )[1]

        # B:F = all monetary columns. Only set numberFormat so the current
        # orange header + alternating white/peach banding stays untouched.
        requests.append(
            {
                'repeatCell':
                    {
                        'range':
                            {
                                'sheetId':
                                    sheet_id,

                                'startRowIndex':
                                    1,

                                'startColumnIndex':
                                    1,

                                'endColumnIndex':
                                    6
                            },

                        'cell':
                            {
                                'userEnteredFormat':
                                    {
                                        'numberFormat':
                                            {
                                                'type':
                                                    'NUMBER',

                                                'pattern':
                                                    '#,##0 "VND"'
                                            }
                                    }
                            },

                        'fields':
                            'userEnteredFormat.numberFormat'
                    }
            }
        )

        # Give the date column enough room while making B:F deliberately
        # wider than the minimum text-fit width so the money/header text has
        # visual breathing room and does not look crowded.
        requests.append(
            {
                'updateDimensionProperties':
                    {
                        'range':
                            {
                                'sheetId':
                                    sheet_id,

                                'dimension':
                                    'COLUMNS',

                                'startIndex':
                                    0,

                                'endIndex':
                                    1
                            },

                        'properties':
                            {
                                'pixelSize':
                                    118
                            },

                        'fields':
                            'pixelSize'
                    }
            }
        )

        requests.append(
            {
                'updateDimensionProperties':
                    {
                        'range':
                            {
                                'sheetId':
                                    sheet_id,

                                'dimension':
                                    'COLUMNS',

                                'startIndex':
                                    1,

                                'endIndex':
                                    6
                            },

                        'properties':
                            {
                                'pixelSize':
                                    165
                            },

                        'fields':
                            'pixelSize'
                    }
            }
        )

        # Center all six header labels without touching their existing color,
        # font, banding, or frozen-row formatting.
        requests.append(
            {
                'repeatCell':
                    {
                        'range':
                            {
                                'sheetId':
                                    sheet_id,

                                'startRowIndex':
                                    0,

                                'endRowIndex':
                                    1,

                                'startColumnIndex':
                                    0,

                                'endColumnIndex':
                                    6
                            },

                        'cell':
                            {
                                'userEnteredFormat':
                                    {
                                        'horizontalAlignment':
                                            'CENTER'
                                    }
                            },

                        'fields':
                            'userEnteredFormat.horizontalAlignment'
                    }
            }
        )

        # Money columns B:F are easier to scan when the numbers line up on
        # their final digit / VND suffix.
        requests.append(
            {
                'repeatCell':
                    {
                        'range':
                            {
                                'sheetId':
                                    sheet_id,

                                'startRowIndex':
                                    1,

                                'startColumnIndex':
                                    1,

                                'endColumnIndex':
                                    6
                            },

                        'cell':
                            {
                                'userEnteredFormat':
                                    {
                                        'horizontalAlignment':
                                            'RIGHT'
                                    }
                            },

                        'fields':
                            'userEnteredFormat.horizontalAlignment'
                    }
            }
        )


        # Header A1:F1: solid pure-black grid/outline around every cell.
        header_border = {
            'style':
                'SOLID',

            'color':
                {
                    'red':
                        0.0,

                    'green':
                        0.0,

                    'blue':
                        0.0
                }
        }

        requests.append(
            {
                'updateBorders':
                    {
                        'range':
                            {
                                'sheetId':
                                    sheet_id,

                                'startRowIndex':
                                    0,

                                'endRowIndex':
                                    1,

                                'startColumnIndex':
                                    0,

                                'endColumnIndex':
                                    6
                            },

                        'top':
                            header_border,

                        'bottom':
                            header_border,

                        'left':
                            header_border,

                        'right':
                            header_border,

                        'innerVertical':
                            header_border
                    }
            }
        )

        # Data A2:F(last calendar day): one shade lighter than black.
        # 0.35 RGB ~= #595959, keeping the grid visible without competing
        # with the stronger header outline.
        data_border = {
            'style':
                'SOLID',

            'color':
                {
                    'red':
                        0.35,

                    'green':
                        0.35,

                    'blue':
                        0.35
                }
        }

        requests.append(
            {
                'updateBorders':
                    {
                        'range':
                            {
                                'sheetId':
                                    sheet_id,

                                'startRowIndex':
                                    1,

                                'endRowIndex':
                                    month_day_count
                                    +
                                    1,

                                'startColumnIndex':
                                    0,

                                'endColumnIndex':
                                    6
                            },

                        'top':
                            data_border,

                        'bottom':
                            data_border,

                        'left':
                            data_border,

                        'right':
                            data_border,

                        'innerHorizontal':
                            data_border,

                        'innerVertical':
                            data_border
                    }
            }
        )

    if requests:
        sheets.batchUpdate(
            spreadsheetId=
                spreadsheet_id,

            body=
                {
                    'requests':
                        requests
                }
        ).execute()



def sync_finance_sheet(include_today=False, interactive=False):
    """Sync historical completed days and optionally today's partial totals."""
    if not google_finance_settings or not google_finance_settings.get('enabled'):
        raise RuntimeError(
            'Google Sheets is not configured. Restart NAU_SERVER.exe with '
            '--configure-google on the server computer.'
        )
    if not google_finance_lock.acquire(blocking=False):
        raise RuntimeError('A Google Sheets sync is already running. Try again shortly.')
    try:
        try:
            from googleapiclient.discovery import build
        except ImportError as error:
            raise RuntimeError(
                'Google libraries missing. Install requirements.txt and rebuild '
                'NAU_SERVER.exe before syncing.'
            ) from error

        through = date.today() - timedelta(days=0 if include_today else 1)
        sales = get_sales_history()
        totals = finance_daily_totals(sales, through)
        credentials = google_finance_credentials(interactive=interactive)
        drive = build('drive', 'v3', credentials=credentials, cache_discovery=False)
        sheets = build('sheets', 'v4', credentials=credentials,
                       cache_discovery=False).spreadsheets()
        folder_id, _ = google_find_or_create(
            drive, None, 'FINANCE', 'application/vnd.google-apps.folder'
        )
        first_year = min((day.year for day in totals), default=through.year)
        links = []
        for year in range(first_year, through.year + 1):
            spreadsheet_id, created = google_find_or_create(
                drive, folder_id, f'{year} revenue',
                'application/vnd.google-apps.spreadsheet'
            )
            google_ensure_month_tabs(sheets, spreadsheet_id, created)
            data = []
            for month in range(1, 13):
                name = calendar.month_name[month]
                data.append({
                    'range': f"'{name}'!A1:F{calendar.monthrange(year, month)[1] + 1}",
                    'values': finance_month_values(year, month, totals, through)
                })
            sheets.values().batchUpdate(
                spreadsheetId=spreadsheet_id,
                body={'valueInputOption': 'RAW', 'data': data}
            ).execute()

            google_format_finance_month_tabs(
                sheets,
                spreadsheet_id,
                year
            )

            links.append({'year': year,
                          'url': f'https://docs.google.com/spreadsheets/d/{spreadsheet_id}/edit'})
        result = {'through': through.isoformat(), 'sales': len(sales),
                  'spreadsheets': links}
        write_log(f'GOOGLE FINANCE SYNC | THROUGH={through} | SALES={len(sales)}')
        return result
    finally:
        google_finance_lock.release()


def google_backup_source_root():
    """
    MAIN is authoritative when available. During failover, BACKUP is
    authoritative and is uploaded instead.
    """
    with storage_lock:
        if storage_mode == 'MAIN' and _storage_root_healthy(main_data_root):
            return Path(main_data_root).resolve(), 'MAIN'

        if _storage_root_healthy(active_data_root):
            return Path(active_data_root).resolve(), 'BACKUP'

        if _storage_root_healthy(backup_data_root):
            return Path(backup_data_root).resolve(), 'BACKUP'

    raise RuntimeError('No healthy NAU data folder is available for Google backup.')


def google_drive_retain_latest_snapshots(drive, root_folder_id, current_snapshot_id=None):
    """Keep the newest two confirmed NAU snapshot folders in our backup root.

    Earlier builds may have used different snapshot names. Identify a snapshot
    by its structure (a direct child folder containing a NAU folder), not by
    a single filename regex. Never touch other folders or files in Drive.
    """
    def list_children(parent_id, query_extra='', fields='id,name,createdTime'):
        items = []
        token = None
        while True:
            query = (f"'{parent_id}' in parents and trashed = false and "
                     "mimeType = 'application/vnd.google-apps.folder'")
            if query_extra:
                query += ' and ' + query_extra
            result = drive.files().list(
                q=query, fields=f'nextPageToken,files({fields})',
                pageSize=1000, pageToken=token
            ).execute()
            items.extend(result.get('files', []))
            token = result.get('nextPageToken')
            if not token:
                return items

    candidates = list_children(root_folder_id)
    snapshots = []
    ignored = []
    for item in candidates:
        item_id = item.get('id')
        if not item_id:
            continue
        # A valid NAU snapshot must contain the NAU root folder. This also
        # recognizes backups made by older versions with different names.
        children = list_children(item_id, "name = 'NAU'", fields='id,name')
        if children:
            snapshots.append(item)
        else:
            ignored.append(item.get('name', '?'))

    print(f'GOOGLE DRIVE BACKUP ROTATION | SNAPSHOTS={len(snapshots)} | '
          f'UNMANAGED_FOLDERS={len(ignored)}', flush=True)
    if ignored:
        write_log('GOOGLE DRIVE BACKUP ROTATION IGNORED | ' + ', '.join(ignored[:30]))

    if current_snapshot_id is not None and not any(item['id'] == current_snapshot_id for item in snapshots):
        raise RuntimeError('Current snapshot lacks a NAU folder or is missing '
                           'from Drive listing; deletion cancelled.')

    # Drive creation timestamps work even when older snapshot names differ.
    snapshots.sort(key=lambda item: (item.get('createdTime', ''), item['id']),
                   reverse=True)
    retained = snapshots[:2]
    if current_snapshot_id is not None and current_snapshot_id not in {item['id'] for item in retained}:
        raise RuntimeError('Current snapshot is not among two newest; '
                           'deletion cancelled.')

    print('GOOGLE DRIVE BACKUP ROTATION KEEP | ' +
          ', '.join(item['name'] for item in retained), flush=True)
    deleted = 0
    failed = []
    for item in snapshots[2:]:
        try:
            drive.files().delete(fileId=item['id']).execute()
            deleted += 1
            message = (f"GOOGLE DRIVE BACKUP PRUNED | SNAPSHOT={item['name']} "
                       f"| ID={item['id']}")
            print(message, flush=True)
            write_log(message)
        except Exception as error:
            failed.append({'name': item['name'], 'error': str(error)})
            message = (f"GOOGLE DRIVE BACKUP PRUNE FAILED | "
                       f"SNAPSHOT={item['name']} | ERROR={error}")
            print(message, flush=True)
            write_log(message)
    print(f'GOOGLE DRIVE BACKUP ROTATION COMPLETE | DELETED={deleted} | '
          f'FAILED={len(failed)} | KEPT={len(retained)}', flush=True)
    return {'retained': [item['name'] for item in retained],
            'deleted': deleted, 'failed': failed,
            'ignored': ignored}


def google_drive_upload_nau_backup():
    """
    Upload a complete snapshot-shaped copy of the authoritative NAU folder
    directly to Google Drive WITHOUT first duplicating the whole NAU folder
    under AppData.

    Older builds created:
        %APPDATA%\\NAUPOSSYS\\cloud_backup_staging\\NAU\\...

    That could temporarily require another full copy of the database on C: and
    fail with WinError 112 when the system drive was low on free space.

    This version enumerates the authoritative folder tree, reads ONE completed
    file at a time into memory, and uploads that immutable byte snapshot. NAU's
    normal data writes are atomic, so JSON files are replaced as complete files
    rather than being edited in place.

    Drive layout remains:
        NAU POS BACKUPS/
            YYYY-MM-DD_HH-MM-SS_MAIN/
                NAU/
                    DATABASE/
                    HISTORY/
                    ASSETS/
                    NAU_LOG.txt
                    NAU_SALES.txt
                    ...
    """
    if not google_finance_settings or not google_finance_settings.get('enabled'):
        raise RuntimeError(
            'Google Drive is not configured. Configure Google on the server first.'
        )

    if not google_backup_lock.acquire(blocking=False):
        raise RuntimeError('A Google Drive NAU backup is already running.')

    try:
        try:
            from googleapiclient.discovery import build
            from googleapiclient.http import MediaIoBaseUpload
        except ImportError as error:
            raise RuntimeError(
                'Google libraries missing. Install requirements.txt and rebuild '
                'NAU_SERVER.exe before using Google Drive backup.'
            ) from error

        source_root, source_label = google_backup_source_root()

        credentials = google_finance_credentials(
            interactive=False
        )

        drive = build(
            'drive',
            'v3',
            credentials=credentials,
            cache_discovery=False
        )
        # google-api-python-client defaults can be too short on slow uploads.
        # This client is local to the backup worker, not the POS API.
        try:
            http_transport = drive._http
            if hasattr(http_transport, 'http'):
                http_transport = http_transport.http
            http_transport.timeout = 120
        except Exception:
            pass

        root_folder_id, _ = google_find_or_create(
            drive,
            None,
            'NAU POS BACKUPS',
            'application/vnd.google-apps.folder'
        )

        timestamp = datetime.now().strftime(
            '%Y-%m-%d_%H-%M-%S'
        )

        snapshot_name = (
            f'{timestamp}_{source_label}'
        )

        snapshot_folder_id, _ = google_find_or_create(
            drive,
            root_folder_id,
            snapshot_name,
            'application/vnd.google-apps.folder'
        )

        nau_drive_id, _ = google_find_or_create(
            drive,
            snapshot_folder_id,
            'NAU',
            'application/vnd.google-apps.folder'
        )

        folder_ids = {
            Path('.'):
                nau_drive_id
        }

        uploaded_files = 0
        uploaded_bytes = 0
        skipped_files = 0

        # Capture the directory/file names first. We do not hold the storage
        # sync lock during internet upload; doing so could stall the POS for
        # minutes. Each individual file is read into bytes before its upload.
        all_paths = sorted(
            source_root.rglob(
                '*'
            )
        )

        # Best-effort total for a useful percentage, without loading file bodies.
        progress_files = []
        for candidate in all_paths:
            if candidate.name.startswith('.nau_storage_probe') or candidate.name.endswith('.tmp'):
                continue
            try:
                if candidate.is_file():
                    progress_files.append((candidate, candidate.stat().st_size))
            except OSError:
                pass
        total_files = len(progress_files)
        total_bytes = sum(size for _, size in progress_files)
        print(f'GOOGLE DRIVE BACKUP PROGRESS | START | FILES={total_files} | BYTES={total_bytes:,}', flush=True)
        with manual_drive_backup_lock:
            if manual_drive_backup_state.get('status') == 'RUNNING':
                manual_drive_backup_state.update(total_files=total_files, total_bytes=total_bytes,
                                                 files=0, bytes=0, percent=0)

        # Create Drive folders first so every file's parent exists.
        for local_path in all_paths:

            try:

                relative = local_path.relative_to(
                    source_root
                )

                if (
                    local_path.name.startswith(
                        '.nau_storage_probe'
                    )
                    or
                    local_path.name.endswith(
                        '.tmp'
                    )
                ):

                    continue

                if not local_path.is_dir():

                    continue

                parent_relative = (
                    relative.parent
                )

                parent_id = (
                    folder_ids[
                        parent_relative
                    ]
                )

                folder_id, _ = google_find_or_create(
                    drive,
                    parent_id,
                    local_path.name,
                    'application/vnd.google-apps.folder'
                )

                folder_ids[
                    relative
                ] = folder_id

            except FileNotFoundError:

                # A directory changed after enumeration. It is safe to skip it;
                # the next hourly backup will capture the new state.
                continue


        for local_path in all_paths:

            relative = local_path.relative_to(
                source_root
            )

            if (
                local_path.name.startswith(
                    '.nau_storage_probe'
                )
                or
                local_path.name.endswith(
                    '.tmp'
                )
            ):

                continue

            try:

                if not local_path.is_file():

                    continue

                # Read one immutable file snapshot into memory. This avoids a
                # second full on-disk NAU copy while keeping the upload stable
                # even if the source file is replaced after this read.
                body = local_path.read_bytes()

            except (
                FileNotFoundError,
                PermissionError,
                OSError
            ) as read_error:

                skipped_files += 1

                try:

                    write_log(
                        'GOOGLE DRIVE BACKUP FILE SKIPPED | '
                        f'FILE={relative} | '
                        f'ERROR={read_error}'
                    )

                except Exception:

                    pass

                continue

            parent_id = folder_ids.get(
                relative.parent
            )

            if parent_id is None:

                skipped_files += 1

                try:

                    write_log(
                        'GOOGLE DRIVE BACKUP FILE SKIPPED | '
                        f'FILE={relative} | '
                        'ERROR=Parent folder was not available.'
                    )

                except Exception:

                    pass

                continue

            metadata = {
                'name':
                    local_path.name,

                'parents':
                    [
                        parent_id
                    ]
            }

            media = MediaIoBaseUpload(
                io.BytesIO(body),
                mimetype='application/octet-stream',
                chunksize=1024 * 1024,
                resumable=True
            )

            # .execute() doesn't give us reliable per-chunk recovery. Keep the
            # resumable session and retry transient timeouts on the SAME request
            # to avoid duplicating uploads after an ambiguous server response.
            request = drive.files().create(
                body=metadata,
                media_body=media,
                fields='id'
            )
            response = None
            failures = 0
            last_reported_percent = -1
            file_size = len(body)

            while response is None:
                try:
                    chunk_status, response = request.next_chunk(num_retries=0)
                    failures = 0
                    chunk_bytes = file_size if response is not None else int(
                        file_size * (chunk_status.progress() if chunk_status is not None else 0))
                    done_bytes = uploaded_bytes + chunk_bytes
                    percent = min(100, int(100 * done_bytes / total_bytes)) if total_bytes else 100
                    with manual_drive_backup_lock:
                        if manual_drive_backup_state.get('status') == 'RUNNING':
                            manual_drive_backup_state.update(percent=percent, bytes=done_bytes,
                                files=uploaded_files, current_file=str(relative), total_files=total_files,
                                total_bytes=total_bytes,
                                message=f'{percent}% | {uploaded_files}/{total_files} files | {relative}')
                    if percent >= last_reported_percent + 5 or response is not None:
                        print(f'GOOGLE DRIVE BACKUP PROGRESS | {percent}% | '
                              f'FILES={uploaded_files}/{total_files} | '
                              f'BYTES={done_bytes:,}/{total_bytes:,} | FILE={relative}', flush=True)
                        last_reported_percent = percent
                except Exception as upload_error:
                    from googleapiclient.errors import HttpError
                    status = getattr(getattr(upload_error, 'resp', None), 'status', None)
                    transient = (
                        isinstance(upload_error, (TimeoutError, ConnectionError, OSError))
                        or isinstance(upload_error, HttpError) and status in (408, 429, 500, 502, 503, 504)
                        or 'timed out' in str(upload_error).lower()
                        or 'temporarily unavailable' in str(upload_error).lower()
                    )
                    if not transient or failures >= 5:
                        raise RuntimeError(
                            f'Google Drive upload failed for {relative} after '
                            f'{failures} retries: {upload_error}'
                        ) from upload_error
                    failures += 1
                    wait_seconds = min(2 ** failures, 30)
                    print(
                        'GOOGLE DRIVE BACKUP RETRY | '
                        f'FILE={relative} | ATTEMPT={failures}/5 | '
                        f'WAIT={wait_seconds}s | ERROR={upload_error}',
                        flush=True
                    )
                    time.sleep(wait_seconds)

            uploaded_files += 1
            uploaded_bytes += len(
                body
            )
            with manual_drive_backup_lock:
                if manual_drive_backup_state.get('status') == 'RUNNING':
                    manual_drive_backup_state['message'] = f'Uploaded {uploaded_files} files ({uploaded_bytes:,} bytes)…'
                    manual_drive_backup_state['files'] = uploaded_files
                    manual_drive_backup_state['bytes'] = uploaded_bytes
                    manual_drive_backup_state['files'] = uploaded_files

        print(f'GOOGLE DRIVE BACKUP PROGRESS | UPLOAD FINISHED | FILES={uploaded_files}/{total_files} | BYTES={uploaded_bytes:,}/{total_bytes:,} | SKIPPED={skipped_files}', flush=True)

        # Do not prune after partial/empty uploads: the two retained copies
        # must not be replaced by a known-incomplete snapshot.
        rotation = {'deleted': 0, 'retained': [], 'failed': []}
        if uploaded_files > 0 and skipped_files == 0:
            try:
                rotation = google_drive_retain_latest_snapshots(
                    drive, root_folder_id, snapshot_folder_id
                )
            except Exception as cleanup_error:
                # Upload succeeded; a cleanup error must not falsely mark the
                # backup itself as failed or cause a duplicate retry.
                message_cleanup = f'GOOGLE DRIVE BACKUP CLEANUP FAILED | {cleanup_error}'
                print(message_cleanup, flush=True)
                write_log(message_cleanup)
                rotation['failed'].append(str(cleanup_error))
        else:
            print(f'GOOGLE DRIVE BACKUP ROTATION SKIPPED | FILES={uploaded_files} | SKIPPED={skipped_files}', flush=True)
            write_log(
                'GOOGLE DRIVE BACKUP CLEANUP SKIPPED | '
                f'FILES={uploaded_files} | SKIPPED={skipped_files} | '
                'Reason: incomplete snapshot; old backups preserved'
            )

        message = (
            'GOOGLE DRIVE NAU BACKUP COMPLETE | '
            f'SOURCE={source_label} | '
            f'FILES={uploaded_files} | '
            f'BYTES={uploaded_bytes} | '
            f'SKIPPED={skipped_files} | '
            f'SNAPSHOT={snapshot_name} | '
            'LOCAL_STAGING=NONE'
        )

        print(
            message,
            flush=True
        )

        write_log(
            message
        )

        return {
            'source':
                source_label,

            'snapshot':
                snapshot_name,

            'files':
                uploaded_files,

            'bytes':
                uploaded_bytes,

            'skipped':
                skipped_files,

            'local_staging':
                False,

            'rotation':
                rotation
        }

    finally:
        google_backup_lock.release()



# Manual Google Drive backups (POS Settings / local desktop dashboard).
# Only one job runs at a time. Progress is authoritative server state.
manual_drive_backup_lock = threading.RLock()
manual_drive_backup_state = {'status': 'IDLE', 'message': 'No manual backup requested.', 'updated_at': None}
NAU_DASHBOARD_BACKUP_KEY = secrets.token_urlsafe(32)

def manual_drive_backup_status():
    with manual_drive_backup_lock:
        return dict(manual_drive_backup_state)

def update_manual_drive_backup(status, message, **extra):
    with manual_drive_backup_lock:
        manual_drive_backup_state.update(status=status, message=str(message),
            updated_at=datetime.now().astimezone().isoformat(timespec='seconds'), **extra)
    print(f'GOOGLE DRIVE MANUAL BACKUP | {status} | {message}', flush=True)

def request_manual_drive_backup():
    with manual_drive_backup_lock:
        if manual_drive_backup_state['status'] in ('RECEIVED', 'RUNNING'):
            return False, dict(manual_drive_backup_state)
        if google_backup_lock.locked():
            return False, {'status':'BUSY', 'message':'An automatic Google Drive backup is already running.'}
        manual_drive_backup_state.clear()
        manual_drive_backup_state.update(status='RECEIVED', message='Server received the backup request.',
            updated_at=datetime.now().astimezone().isoformat(timespec='seconds'))
    def worker():
        try:
            update_manual_drive_backup('RUNNING', 'Preparing and uploading the NAU folder…')
            result = google_drive_upload_nau_backup()
            update_manual_drive_backup('COMPLETE', 'Google Drive confirmed the backup.',
                snapshot=result.get('snapshot'), files=result.get('files'), bytes=result.get('bytes'))
        except Exception as exc:
            update_manual_drive_backup('FAILED', str(exc))
            try:
                write_log(f'GOOGLE DRIVE NAU BACKUP ERROR | {exc}')
            except Exception:
                pass
    threading.Thread(target=worker, daemon=True, name='nau-manual-google-backup').start()
    return True, manual_drive_backup_status()

def request_manual_drive_prune():
    """Prune old Drive snapshots without creating another backup."""
    if not google_backup_lock.acquire(blocking=False):
        return False, 'Google Drive backup or pruning is already running.'

    def worker():
        try:
            print('GOOGLE DRIVE MANUAL PRUNE | STARTED', flush=True)
            from googleapiclient.discovery import build
            credentials = google_finance_credentials(interactive=False)
            drive = build('drive', 'v3', credentials=credentials, cache_discovery=False)
            root_id, _ = google_find_or_create(
                drive, None, 'NAU POS BACKUPS', 'application/vnd.google-apps.folder'
            )
            result = google_drive_retain_latest_snapshots(drive, root_id)
            print(f"GOOGLE DRIVE MANUAL PRUNE | COMPLETE | DELETED={result['deleted']} "
                  f"| FAILED={len(result['failed'])} | KEPT={len(result['retained'])}", flush=True)
        except Exception as exc:
            print(f'GOOGLE DRIVE MANUAL PRUNE | FAILED | {exc}', flush=True)
            try:
                write_log(f'GOOGLE DRIVE MANUAL PRUNE ERROR | {exc}')
            except Exception:
                pass
        finally:
            google_backup_lock.release()

    try:
        threading.Thread(target=worker, daemon=True, name='nau-manual-google-prune').start()
    except Exception:
        google_backup_lock.release()
        raise
    return True, 'Pruning started in background.'


def dashboard_backup_authorized(handler):
    from ipaddress import ip_address
    try:
        address = ip_address(handler.client_address[0])
        return address.is_loopback and hmac.compare_digest(
            str(handler.headers.get('X-NAU-Dashboard-Key', '')), NAU_DASHBOARD_BACKUP_KEY)
    except (ValueError, TypeError):
        return False

def nau_print_console_help():
    """Print the operator command menu only when explicitly requested."""
    commands = (
        ('1', 'Google Drive backup now'),
        ('2', 'Manual backup status'),
        ('3', 'Prune old Google Drive backups (keep newest 2)'),
        ('4', 'Test Python free-threading'),
        ('5', 'Test POS listener'),
        ('7', 'Test database storage'),
        ('8', 'Test local backup storage'),
        ('11', 'Test Google Drive connectivity'),
        ('12', 'Test Google Sheets finance'),
        ('13', 'Run all available server diagnostics'),
        ('help', 'Show this command menu'),
        ('Ctrl+C', 'Stop server'),
    )
    width = max(52, max(len(key) + len(description) + 7 for key, description in commands))
    border = '=' * width
    print('\n' + border, flush=True)
    print('NAU SERVER COMMANDS'.center(width), flush=True)
    print(border, flush=True)
    for key, description in commands:
        print(f'  {key:<9} {description}', flush=True)
    print(border + '\n', flush=True)


NAU_DIAGNOSTIC_COMMANDS = {
    '4': 'Python free-threading',
    '5': 'POS listener',
    '7': 'Database storage',
    '8': 'Local backup storage',
    '11': 'Google Drive',
    '12': 'Google Sheets',
}
_nau_diagnostic_command_lock = threading.Lock()

def request_console_diagnostics(command, google_enabled):
    if not _nau_diagnostic_command_lock.acquire(blocking=False):
        print('[TEST] Another diagnostic is already running.', flush=True)
        return
    selected = None if command == '13' else {NAU_DIAGNOSTIC_COMMANDS[command]}
    def worker():
        try:
            _nau_startup_self_test(
                google_enabled=google_enabled,
                selected=selected,
            )
        except Exception as error:
            print(f'[TEST] Unexpected diagnostic failure: {type(error).__name__}: {error}', flush=True)
        finally:
            _nau_diagnostic_command_lock.release()
    try:
        threading.Thread(target=worker, daemon=True, name='nau-console-diagnostic').start()
    except Exception:
        _nau_diagnostic_command_lock.release()
        raise

def nau_server_console_commands(google_enabled):
    """Read operator commands without blocking POS HTTP; menu appears on help."""
    while not storage_monitor_stop.is_set():
        try:
            command = input().strip().lower()
        except EOFError:
            # No interactive console (for example, the packaged GUI build).
            return
        except (OSError, ValueError):
            return
        except KeyboardInterrupt:
            # KeyboardInterrupt is normally delivered to the main thread.
            return
        if not command:
            continue
        if command == '1':
            if not google_enabled:
                print('[BACKUP] Google integration is not configured/enabled.', flush=True)
                continue
            try:
                accepted, state = request_manual_drive_backup()
                if accepted:
                    print('[BACKUP] Request accepted; uploading in background.', flush=True)
                else:
                    print(f"[BACKUP] Not started: {state.get('message', 'Backup busy')}", flush=True)
            except Exception as exc:
                print(f'[BACKUP] Failed to request backup: {exc}', flush=True)
        elif command == '2':
            state = manual_drive_backup_status()
            print(f"[BACKUP] {state.get('status', 'UNKNOWN')} | {state.get('message', '')}", flush=True)
            for key in ('snapshot', 'files', 'bytes', 'updated_at'):
                if key in state:
                    print(f'         {key}: {state[key]}', flush=True)
        elif command == '3':
            if not google_enabled:
                print('[PRUNE] Google integration is not configured/enabled.', flush=True)
                continue
            print('[PRUNE] This permanently deletes older managed NAU Drive snapshots.', flush=True)
            print('[PRUNE] The newest TWO recognized snapshots will be kept.', flush=True)
            try:
                confirmation = input('Delete older backups? [y/N]: ').strip().lower()
            except (EOFError, OSError, ValueError):
                return
            if confirmation not in ('y', 'yes'):
                print('[PRUNE] Cancelled.', flush=True)
                continue
            try:
                accepted, message = request_manual_drive_prune()
                print(f'[PRUNE] {message}', flush=True)
            except Exception as exc:
                print(f'[PRUNE] Failed to start: {exc}', flush=True)
        elif command in NAU_DIAGNOSTIC_COMMANDS or command == '13':
            request_console_diagnostics(command, google_enabled)
        elif command in ('h', 'help', '?'):
            nau_print_console_help()
        else:
            print(f'[COMMANDS] Unknown command: {command!r}. Type help for the command list.', flush=True)


def google_drive_backup_loop():
    """
    Upload the whole authoritative NAU folder once every hour.
    First automatic upload occurs one hour after server startup.
    """
    while not storage_monitor_stop.wait(3600):
        try:
            google_drive_upload_nau_backup()
        except Exception as error:
            message = f'GOOGLE DRIVE NAU BACKUP ERROR | {error}'
            print(message, flush=True)
            try:
                write_log(message)
            except Exception:
                pass


def finance_auto_sync_loop(first_google_setup):
    """Catch up at startup, then export completed days at 00:10 local time."""
    last_completed = None
    last_attempt = 0
    first_attempt = True
    while True:
        now = datetime.now()
        through = now.date() - timedelta(days=1)
        ready = first_attempt or (now.hour > 0 or now.minute >= 10)
        if ready and through != last_completed and time.monotonic() - last_attempt >= 600:
            last_attempt = time.monotonic()
            try:
                sync_finance_sheet(interactive=first_google_setup and first_attempt)
                last_completed = through
            except Exception as error:
                write_log(f'GOOGLE FINANCE SYNC ERROR | {error}')
                print(f'Google Finance sync failed: {error}', flush=True)
        first_attempt = False
        time.sleep(30)


def get_daily_sales_file(
    paid_at
):

    date_text = paid_at.strftime(
        '%Y-%m-%d'
    )

    matching_files = sorted(
        sales_history_folder.glob(
            f'{date_text}_*.json'
        )
    )

    if matching_files:

        file_path = (
            matching_files[0]
        )

        data = read_json_file(
            file_path
        )

        if str(
            data.get(
                'date',
                ''
            )
        ) != date_text:

            raise ValueError(
                f'Sales history date mismatch in '
                f'{file_path.name}.'
            )

        if not isinstance(
            data.get(
                'sales',
                []
            ),
            list
        ):

            raise ValueError(
                f'Invalid sales history file: '
                f'{file_path.name}.'
            )

        return (
            file_path,
            data
        )

    base_name = paid_at.strftime(
        '%Y-%m-%d_%H-%M-%S'
    )

    file_path = (
        sales_history_folder /
        f'{base_name}.json'
    )

    counter = 1

    while file_path.exists():

        file_path = (
            sales_history_folder /
            f'{base_name}_{counter}.json'
        )

        counter += 1

    created_at = paid_at.isoformat(
        timespec='seconds'
    )

    data = {

        'date':
            date_text,

        'created_at':
            created_at,

        'last_updated_at':
            created_at,

        'sale_count':
            0,

        'totals': {

            'base_sales':
                0,

            'substitution_charges':
                0,

            'subtotal':
                0,

            'discounts':
                0,

            'revenue':
                0,

            'ingredient_cost':
                0,

            'gross_profit':
                0

        },

        'sales':
            []

    }

    return (
        file_path,
        data
    )


def rebuild_daily_sales_totals(
    history_data
):

    base_sales = Decimal(
        '0'
    )

    substitution_charges = Decimal(
        '0'
    )

    subtotal = Decimal(
        '0'
    )

    discounts = Decimal(
        '0'
    )

    revenue = Decimal(
        '0'
    )

    ingredient_cost = Decimal(
        '0'
    )

    gross_profit = Decimal(
        '0'
    )

    sales = history_data.get(
        'sales',
        []
    )

    for sale in sales:

        base_sales += Decimal(
            str(
                sale.get(
                    'base_sale_price',
                    0
                )
            )
        )

        substitution_charges += Decimal(
            str(
                sale.get(
                    'substitution_charge',
                    0
                )
            )
        )

        sale_subtotal = sale.get(
            'subtotal'
        )

        if sale_subtotal is None:

            sale_subtotal = (
                Decimal(
                    str(
                        sale.get(
                            'base_sale_price',
                            0
                        )
                    )
                )
                +
                Decimal(
                    str(
                        sale.get(
                            'substitution_charge',
                            0
                        )
                    )
                )
            )

        subtotal += Decimal(
            str(
                sale_subtotal
            )
        )

        discounts += Decimal(
            str(
                sale.get(
                    'discount_amount',
                    0
                )
            )
        )

        revenue += Decimal(
            str(
                sale.get(
                    'total',
                    0
                )
            )
        )

        ingredient_cost += Decimal(
            str(
                sale.get(
                    'ingredient_cost',
                    0
                )
            )
        )

        gross_profit += Decimal(
            str(
                sale.get(
                    'gross_profit',
                    0
                )
            )
        )

    history_data[
        'sale_count'
    ] = len(
        sales
    )

    history_data[
        'totals'
    ] = {

        'base_sales':
            money_output(
                base_sales
            ),

        'substitution_charges':
            money_output(
                substitution_charges
            ),

        'subtotal':
            money_output(
                subtotal
            ),

        'discounts':
            money_output(
                discounts
            ),

        'revenue':
            money_output(
                revenue
            ),

        'ingredient_cost':
            money_output(
                ingredient_cost
            ),

        'gross_profit':
            money_output(
                gross_profit
            )

    }


def get_original_sale_total(
    sale
):

    if not isinstance(
        sale,
        dict
    ):

        raise ValueError(
            'Invalid sale record.'
        )

    if 'original_total' in sale:

        original_total = money(
            sale[
                'original_total'
            ]
        )

    else:

        original_total = money(
            sale.get(
                'total',
                0
            )
        )

    if original_total < 0:

        raise ValueError(
            'Sale original total cannot be negative.'
        )

    return original_total



def build_sale_adjustment_result(
    sale,
    history_file,
    already_refunded=False,
    already_voided=False
):

    return {

        'success':
            True,

        'transaction_id':
            sale.get(
                'transaction_id'
            ),

        'original_total':
            money_output(
                get_original_sale_total(
                    sale
                )
            ),

        'total':
            money_output(
                sale.get(
                    'total',
                    0
                )
            ),

        'refunded':
            sale.get(
                'refunded'
            )
            is True,

        'voided':
            sale.get(
                'voided'
            )
            is True,

        'timeVR':
            sale.get(
                'timeVR'
            ),

        'already_refunded':
            already_refunded,

        'already_voided':
            already_voided,

        'history_file':
            Path(
                history_file
            ).name

    }



def refund_sale(
    transaction_id
):

    try:

        transaction_id = (
            validate_transaction_id(
                transaction_id
            )
        )

    except Exception as error:

        return {

            'success':
                False,

            'error':
                str(error)

        }

    with finalization_lock:

        try:

            existing = (
                find_sale_by_transaction_id(
                    transaction_id
                )
            )

            if existing is None:

                return {

                    'success':
                        False,

                    'not_found':
                        True,

                    'error':
                        'Sale not found.'

                }

            sale = existing[
                'sale'
            ]


            if (
                sale.get(
                    'sale_kind'
                )
                ==
                'INTERNAL_CONSUMPTION'
            ):
                return {
                    'success':
                        False,

                    'error':
                        'Internal-use records cannot be refunded.'
                }

            history_data = existing[
                'history'
            ]

            history_file = existing[
                'file'
            ]

            if sale.get(
                'voided'
            ) is True:

                return {

                    'success':
                        False,

                    'error':
                        'A voided sale cannot be refunded.'

                }

            if sale.get(
                'refunded'
            ) is True:

                return build_sale_adjustment_result(
                    sale,
                    history_file,
                    already_refunded=True
                )

            original_total = (
                get_original_sale_total(
                    sale
                )
            )

            timestamp = (
                datetime.now()
                .isoformat(
                    timespec='seconds'
                )
            )

            if 'original_total' not in sale:

                sale[
                    'original_total'
                ] = money_output(
                    original_total
                )

            sale[
                'total'
            ] = 0

            sale[
                'refunded'
            ] = True

            sale[
                'voided'
            ] = False

            sale[
                'timeVR'
            ] = timestamp

            history_data[
                'last_updated_at'
            ] = timestamp

            rebuild_daily_sales_totals(
                history_data
            )

            write_json_file_atomic(
                history_file,
                history_data
            )


            refresh_cost_history_best_effort(
                'REFUND'
            )

            try:

                write_log(
                    f'SALE REFUNDED | '
                    f'TX={transaction_id} | '
                    f'ORIGINAL_TOTAL={money_output(original_total)} | '
                    f'TOTAL=0 | '
                    f'TIMEVR={timestamp} | '
                    f'HISTORY={history_file.name}'
                )

            except Exception:

                pass

            return build_sale_adjustment_result(
                sale,
                history_file
            )

        except Exception as error:

            try:

                write_log(
                    f'SALE REFUND FAILED | '
                    f'TX={transaction_id} | '
                    f'ERROR={error}'
                )

            except Exception:

                pass

            return {

                'success':
                    False,

                'error':
                    str(error)

            }



def get_void_inventory_restore_plan(
    sale
):

    if not isinstance(
        sale,
        dict
    ):

        raise ValueError(
            'Invalid sale record.'
        )

    ingredients_used = sale.get(
        'ingredients_used'
    )

    if ingredients_used is None:

        raise ValueError(
            'Sale does not contain the inventory history required for voiding.'
        )

    if not isinstance(
        ingredients_used,
        list
    ):

        raise ValueError(
            'Invalid sale inventory history.'
        )

    restore_amounts = {}

    for ingredient in ingredients_used:

        if not isinstance(
            ingredient,
            dict
        ):

            raise ValueError(
                'Invalid ingredient snapshot in sale history.'
            )

        ingredient_id = (
            validate_ingredient_id(
                ingredient.get(
                    'id'
                )
            )
        )

        try:

            amount = Decimal(
                str(
                    ingredient.get(
                        'amount',
                        0
                    )
                )
            )

        except Exception:

            raise ValueError(
                f'Invalid historical ingredient amount: '
                f'{ingredient_id}'
            )

        if not amount.is_finite():

            raise ValueError(
                f'Invalid historical ingredient amount: '
                f'{ingredient_id}'
            )

        if amount < 0:

            raise ValueError(
                f'Historical ingredient amount cannot be negative: '
                f'{ingredient_id}'
            )

        restore_amounts[
            ingredient_id
        ] = (
            restore_amounts.get(
                ingredient_id,
                Decimal('0')
            )
            +
            amount
        )

    return restore_amounts



@synchronized(ingredient_db_lock)
def void_sale(
    transaction_id,
    actor=None
):

    try:

        transaction_id = (
            validate_transaction_id(
                transaction_id
            )
        )

    except Exception as error:

        return {

            'success':
                False,

            'error':
                str(error)

        }

    with finalization_lock:

        journal_file = None

        history_committed = False

        try:

            existing = (
                find_sale_by_transaction_id(
                    transaction_id
                )
            )

            if existing is None:

                return {

                    'success':
                        False,

                    'not_found':
                        True,

                    'error':
                        'Sale not found.'

                }

            sale = existing[
                'sale'
            ]


            if (
                sale.get(
                    'sale_kind'
                )
                ==
                'INTERNAL_CONSUMPTION'
            ):
                return {
                    'success':
                        False,

                    'error':
                        'Internal-use records cannot be voided.'
                }

            history_data = existing[
                'history'
            ]

            history_file = existing[
                'file'
            ]

            if sale.get(
                'refunded'
            ) is True:

                return {

                    'success':
                        False,

                    'error':
                        'A refunded sale cannot be voided.'

                }

            if sale.get(
                'voided'
            ) is True:

                return build_sale_adjustment_result(
                    sale,
                    history_file,
                    already_voided=True
                )

            original_total = (
                get_original_sale_total(
                    sale
                )
            )

            restore_amounts = (
                get_void_inventory_restore_plan(
                    sale
                )
            )

            inventory_before = {}

            inventory_after = {}

            for (
                ingredient_id,
                restore_amount
            ) in restore_amounts.items():

                ingredient_file = (
                    find_ingredient_anywhere(
                        ingredient_id
                    )
                )

                if ingredient_file is None:

                    raise ValueError(
                        f'Cannot void sale because ingredient '
                        f'no longer exists: {ingredient_id}'
                    )

                ingredient_data = (
                    read_ingredient_file(
                        ingredient_file
                    )
                )

                try:

                    current_stock = Decimal(
                        str(
                            ingredient_data.get(
                                'stock',
                                0
                            )
                        )
                    )

                except Exception:

                    raise ValueError(
                        f'Invalid current stock for ingredient: '
                        f'{ingredient_id}'
                    )

                if not current_stock.is_finite():

                    raise ValueError(
                        f'Invalid current stock for ingredient: '
                        f'{ingredient_id}'
                    )

                inventory_before[
                    ingredient_id
                ] = ingredient_data

                inventory_after[
                    ingredient_id
                ] = (
                    current_stock
                    +
                    restore_amount
                )

            timestamp = (
                datetime.now()
                .isoformat(
                    timespec='seconds'
                )
            )

            journal_file = (
                get_pending_adjustment_file(
                    transaction_id,
                    'VOID'
                )
            )

            journal_data = {

                'transaction_id':
                    transaction_id,

                'action':
                    'VOID',

                'created_at':
                    timestamp,

                'history_file':
                    history_file.name,

                'inventory_before':
                    inventory_before

            }

            write_json_file_atomic(
                journal_file,
                journal_data
            )

            for (
                ingredient_id,
                new_stock
            ) in inventory_after.items():

                ingredient_file = (
                    find_ingredient_anywhere(
                        ingredient_id
                    )
                )

                if ingredient_file is None:

                    raise ValueError(
                        f'Ingredient disappeared during void: '
                        f'{ingredient_id}'
                    )

                ingredient_data = (
                    inventory_before[
                        ingredient_id
                    ].copy()
                )

                ingredient_data[
                    'stock'
                ] = decimal_output(
                    new_stock
                )

                write_json_file_atomic(
                    ingredient_file,
                    ingredient_data
                )

            if 'original_total' not in sale:

                sale[
                    'original_total'
                ] = money_output(
                    original_total
                )

            sale[
                'total'
            ] = 0

            sale[
                'refunded'
            ] = False

            sale[
                'voided'
            ] = True

            sale[
                'timeVR'
            ] = timestamp

            history_data[
                'last_updated_at'
            ] = timestamp

            rebuild_daily_sales_totals(
                history_data
            )

            write_json_file_atomic(
                history_file,
                history_data
            )


            refresh_cost_history_best_effort(
                'VOID'
            )

            history_committed = True

            try:

                void_history_entries = []

                for (
                    ingredient_id,
                    restore_amount
                ) in restore_amounts.items():

                    ingredient_data = (
                        inventory_before[
                            ingredient_id
                        ]
                    )

                    current_stock = Decimal(
                        str(
                            ingredient_data.get(
                                'stock',
                                0
                            )
                        )
                    )

                    void_history_entries.append(
                        {
                            'timestamp':
                                timestamp,

                            'ingredient_id':
                                ingredient_id,

                            'ingredient_name':
                                ingredient_data.get(
                                    'name',
                                    ingredient_id
                                ),

                            'unit':
                                ingredient_data.get(
                                    'unit',
                                    ''
                                ),

                            'change':
                                restore_amount,

                            'stock_before':
                                current_stock,

                            'stock_after':
                                inventory_after[
                                    ingredient_id
                                ],

                            'reason':
                                'VOID RESTORE',

                            'source':
                                'VOID',

                            'actor':
                                actor,

                            'transaction_id':
                                transaction_id,

                            'table':
                                sale.get(
                                    'table'
                                ),

                            'details':
                                'Inventory restored because the sale was voided.'
                        }
                    )

                append_ingredient_history_entries(
                    void_history_entries
                )

            except Exception as history_error:

                try:

                    write_log(
                        f'INGREDIENT VOID HISTORY FAILED | '
                        f'TX={transaction_id} | '
                        f'ERROR={history_error}'
                    )

                except Exception:

                    pass

            try:

                if (
                    journal_file is not None
                    and
                    journal_file.exists()
                ):

                    journal_file.unlink()

            except Exception as cleanup_error:

                try:

                    write_log(
                        f'SALE VOID JOURNAL CLEANUP FAILED | '
                        f'TX={transaction_id} | '
                        f'ERROR={cleanup_error}'
                    )

                except Exception:

                    pass

            try:

                restored_text = ','.join(
                    (
                        f'{ingredient_id}:'
                        f'{decimal_output(amount)}'
                    )

                    for (
                        ingredient_id,
                        amount
                    ) in restore_amounts.items()
                )

                write_log(
                    f'SALE VOIDED | '
                    f'TX={transaction_id} | '
                    f'ORIGINAL_TOTAL={money_output(original_total)} | '
                    f'TOTAL=0 | '
                    f'TIMEVR={timestamp} | '
                    f'INVENTORY_RESTORED={restored_text or "NONE"} | '
                    f'HISTORY={history_file.name}'
                )

            except Exception:

                pass

            return build_sale_adjustment_result(
                sale,
                history_file
            )

        except Exception as error:

            rollback_error = None

            if not history_committed:

                try:

                    if (
                        journal_file is not None
                        and
                        journal_file.exists()
                    ):

                        journal_data = (
                            read_json_file(
                                journal_file
                            )
                        )

                        restore_inventory_snapshot(
                            journal_data.get(
                                'inventory_before',
                                {}
                            )
                        )

                        journal_file.unlink()

                except Exception as recovery_error:

                    rollback_error = (
                        recovery_error
                    )

            try:

                if rollback_error is None:

                    write_log(
                        f'SALE VOID FAILED | '
                        f'TX={transaction_id} | '
                        f'ERROR={error}'
                    )

                else:

                    write_log(
                        f'SALE VOID FAILED | '
                        f'TX={transaction_id} | '
                        f'ERROR={error} | '
                        f'ROLLBACK_ERROR={rollback_error}'
                    )

            except Exception:

                pass

            result = {

                'success':
                    False,

                'error':
                    str(error)

            }

            if rollback_error is not None:

                result[
                    'rollback_error'
                ] = str(
                    rollback_error
                )

            return result



def recover_pending_adjustments():

    if not pending_adjustments_folder.exists():

        return

    for journal_file in sorted(
        pending_adjustments_folder.glob(
            '*.json'
        )
    ):

        try:

            journal = read_json_file(
                journal_file
            )

            transaction_id = (
                validate_transaction_id(
                    journal[
                        'transaction_id'
                    ]
                )
            )

            action = normalize_text(
                journal.get(
                    'action',
                    ''
                )
            )

            if action != 'VOID':

                raise ValueError(
                    f'Unsupported pending sale adjustment action: '
                    f'{action or "UNKNOWN"}'
                )

            existing = (
                find_sale_by_transaction_id(
                    transaction_id
                )
            )

            if (
                existing is not None
                and
                existing[
                    'sale'
                ].get(
                    'voided'
                )
                is True
            ):

                journal_file.unlink()

                write_log(
                    f'SALE ADJUSTMENT RECOVERY COMPLETE | '
                    f'TX={transaction_id} | '
                    f'ACTION=VOID_HISTORY_ALREADY_COMMITTED'
                )

                continue

            restore_inventory_snapshot(
                journal.get(
                    'inventory_before',
                    {}
                )
            )

            journal_file.unlink()

            write_log(
                f'SALE ADJUSTMENT RECOVERY COMPLETE | '
                f'TX={transaction_id} | '
                f'ACTION=VOID_INVENTORY_ROLLED_BACK'
            )

        except Exception as error:

            write_log(
                f'SALE ADJUSTMENT RECOVERY FAILED | '
                f'FILE={journal_file.name} | '
                f'ERROR={error}'
            )

            raise



def append_sale_to_history(
    sale_record,
    paid_at
):

    transaction_id = (
        validate_transaction_id(
            sale_record[
                'transaction_id'
            ]
        )
    )

    existing = (
        find_sale_by_transaction_id(
            transaction_id
        )
    )

    if existing is not None:

        return {

            'already_exists':
                True,

            'file':
                existing[
                    'file'
                ],

            'sale':
                existing[
                    'sale'
                ]

        }

    file_path, history_data = (
        get_daily_sales_file(
            paid_at
        )
    )

    history_data[
        'sales'
    ].append(
        sale_record
    )

    history_data[
        'last_updated_at'
    ] = paid_at.isoformat(
        timespec='seconds'
    )

    rebuild_daily_sales_totals(
        history_data
    )

    write_json_file_atomic(
        file_path,
        history_data
    )

    return {

        'already_exists':
            False,

        'file':
            file_path,

        'sale':
            sale_record

    }


def restore_inventory_snapshot(
    inventory_before
):

    if not isinstance(
        inventory_before,
        dict
    ):

        raise ValueError(
            'Invalid inventory recovery snapshot.'
        )

    for (
        ingredient_id,
        ingredient_data
    ) in inventory_before.items():

        ingredient_file = (
            find_ingredient_anywhere(
                ingredient_id
            )
        )

        if ingredient_file is None:

            raise ValueError(
                f'Cannot recover ingredient: '
                f'{ingredient_id}'
            )

        write_json_file_atomic(
            ingredient_file,
            ingredient_data
        )


def recover_pending_sales():

    if not pending_sales_folder.exists():

        return

    for journal_file in sorted(
        pending_sales_folder.glob(
            '*.json'
        )
    ):

        try:

            journal = read_json_file(
                journal_file
            )

            transaction_id = (
                validate_transaction_id(
                    journal[
                        'transaction_id'
                    ]
                )
            )

            existing = (
                find_sale_by_transaction_id(
                    transaction_id
                )
            )

            if existing is not None:

                journal_file.unlink()

                write_log(
                    f'SALE RECOVERY COMPLETE | '
                    f'TX={transaction_id} | '
                    f'ACTION=HISTORY_ALREADY_COMMITTED'
                )

                continue

            restore_inventory_snapshot(
                journal.get(
                    'inventory_before',
                    {}
                )
            )

            journal_file.unlink()

            write_log(
                f'SALE RECOVERY COMPLETE | '
                f'TX={transaction_id} | '
                f'ACTION=INVENTORY_ROLLED_BACK'
            )

        except Exception as error:

            write_log(
                f'SALE RECOVERY FAILED | '
                f'FILE={journal_file.name} | '
                f'ERROR={error}'
            )

            raise



def build_shot_special_recipe():

    return {

        'id':
            SPECIAL_RECIPE_SHOT_ID,

        'name':
            SPECIAL_RECIPE_SHOT_ID,

        'special_type':
            SPECIAL_RECIPE_STANDALONE_INGREDIENT,

        'system':
            True

    }


def build_bespoke_special_recipe():

    return {

        'id':
            SPECIAL_RECIPE_BESPOKE_ID,

        'name':
            'Bespoke',

        'special_type':
            SPECIAL_RECIPE_CUSTOM_ONE_TIME,

        'SALE_P':
            money_output(
                BESPOKE_FIXED_SALE_PRICE
            ),

        'system':
            True

    }


def build_classic_special_recipe():

    return {

        'id':
            SPECIAL_RECIPE_CLASSIC_ID,

        'name':
            'Classic',

        'special_type':
            SPECIAL_RECIPE_CLASSIC_OFF_MENU,

        # SALE_P is only a display/default value. The actual sale price is
        # selected per order line and is validated server-side against
        # CLASSIC_ALLOWED_SALE_PRICES.
        'SALE_P':
            money_output(
                CLASSIC_ALLOWED_SALE_PRICES[0]
            ),

        'price_options': [
            money_output(
                price
            )
            for price in CLASSIC_ALLOWED_SALE_PRICES
        ],

        'system':
            True

    }


@synchronized(recipe_db_lock)
def ensure_special_recipes():

    special_recipes_folder.mkdir(
        parents=True,
        exist_ok=True
    )

    expected_recipes = [
        (
            shot_recipe_file,
            build_shot_special_recipe(),
            SPECIAL_RECIPE_SHOT_ID,
            SPECIAL_RECIPE_STANDALONE_INGREDIENT
        ),
        (
            bespoke_recipe_file,
            build_bespoke_special_recipe(),
            SPECIAL_RECIPE_BESPOKE_ID,
            SPECIAL_RECIPE_CUSTOM_ONE_TIME
        ),
        (
            classic_recipe_file,
            build_classic_special_recipe(),
            SPECIAL_RECIPE_CLASSIC_ID,
            SPECIAL_RECIPE_CLASSIC_OFF_MENU
        )
    ]

    for (
        file_path,
        expected,
        recipe_id,
        special_type
    ) in expected_recipes:

        if not file_path.exists():

            write_json_file_atomic(
                file_path,
                expected
            )

            write_log(
                f'SPECIAL RECIPE CREATED | '
                f'ID={recipe_id} | '
                f'TYPE={special_type}'
            )

            continue

        try:

            existing = read_json_file(
                file_path
            )

        except Exception as error:

            raise ValueError(
                f'Special recipe {recipe_id} could not be read: '
                f'{error}'
            )

        if not isinstance(
            existing,
            dict
        ):

            raise ValueError(
                f'Special recipe {recipe_id} must contain a JSON object.'
            )

        needs_repair = (

            normalize_text(
                existing.get(
                    'id',
                    ''
                )
            )
            !=
            recipe_id

            or

            str(
                existing.get(
                    'name',
                    ''
                )
            ).strip()
            !=
            str(
                expected.get(
                    'name',
                    ''
                )
            ).strip()

            or

            normalize_text(
                existing.get(
                    'special_type',
                    ''
                )
            )
            !=
            special_type

            or

            existing.get(
                'system'
            )
            is not True

            or

            (
                recipe_id ==
                SPECIAL_RECIPE_BESPOKE_ID
                and
                existing.get(
                    'SALE_P'
                )
                !=
                expected.get(
                    'SALE_P'
                )
            )

            or

            (
                recipe_id ==
                SPECIAL_RECIPE_CLASSIC_ID
                and
                (
                    existing.get(
                        'SALE_P'
                    )
                    !=
                    expected.get(
                        'SALE_P'
                    )
                    or
                    existing.get(
                        'price_options'
                    )
                    !=
                    expected.get(
                        'price_options'
                    )
                )
            )

        )

        if needs_repair:

            write_json_file_atomic(
                file_path,
                expected
            )

            write_log(
                f'SPECIAL RECIPE REPAIRED | '
                f'ID={recipe_id} | '
                f'TYPE={special_type}'
            )


