def initialize_nau_assets():
    """
    Runtime brand assets live beside DATABASE/HISTORY inside the selected
    NAU data root:

        NAU/
        ├─ ASSETS/
        │  ├─ nau-logo-header.png
        │  └─ nau-logo-receipt.png
        ├─ DATABASE/
        ├─ HISTORY/
        └─ TEMPS/
           └─ ORDER DATA/

    Existing user-provided assets are never overwritten.
    Missing logo assets are recreated from embedded server fallbacks.
    """

    assets_folder.mkdir(
        parents=True,
        exist_ok=True
    )

    asset_specs = [
        (
            'nau-logo-header.png',
            NAU_LOGO_HEADER_PNG_BASE64
        ),
        (
            'nau-logo-receipt.png',
            NAU_LOGO_RECEIPT_PNG_BASE64
        )
    ]

    for filename, base64_payload in asset_specs:

        asset_target = (
            assets_folder /
            filename
        )

        if asset_target.exists():
            continue

        try:
            logo_bytes = base64.b64decode(
                base64_payload,
                validate=False
            )

            if not logo_bytes.startswith(
                b'\x89PNG\r\n\x1a\n'
            ):
                raise ValueError(
                    f'Embedded asset data is not a valid PNG: {filename}'
                )

            temporary = asset_target.with_name(
                f'.{filename}.tmp'
            )

            try:
                temporary.write_bytes(
                    logo_bytes
                )

                os.replace(
                    temporary,
                    asset_target
                )

            finally:
                temporary.unlink(
                    missing_ok=True
                )

            print(
                f'Náu asset initialized: {asset_target}',
                flush=True
            )

        except Exception as error:
            # Branding must never prevent the POS server from starting.
            print(
                'WARNING: Could not initialize Náu asset '
                f'({filename}): {error}',
                flush=True
            )


