def ensure_native_free_threading():

    if (
        FREE_THREADED_BUILD
        and
        GIL_ENABLED is False
    ):

        return


    # Avoid an infinite relaunch loop if the Windows Python launcher is
    # misconfigured or 3.14t is not actually available.
    if (
        os.environ.get(
            'NAU_FREE_THREADED_RELAUNCH'
        )
        ==
        '1'
    ):

        raise RuntimeError(
            'NAU POS tried to relaunch with Python 3.14t and GIL disabled, '
            'but the new process is still not free-threaded. '
            'Verify with: '
            'py -V:3.14t -X gil=0 -c '
            '"import sys,sysconfig; '
            'print(sysconfig.get_config_var(\'Py_GIL_DISABLED\')); '
            'print(sys._is_gil_enabled())"'
        )


    launcher = shutil.which(
        'py'
    )


    if launcher is None:

        raise RuntimeError(
            'NAU POS needs the Windows Python launcher to automatically '
            'switch to Python 3.14t. Install/register Python 3.14t first.'
        )


    script_path = str(
        Path(
            __file__
        ).resolve()
    )


    relaunch_args = [
        launcher,
        '-V:3.14t',
        '-X',
        'gil=0',
        script_path,
        *sys.argv[1:]
    ]


    print()
    print('==============================================')
    print('       NAU POS FREE-THREADED RELAUNCH')
    print('==============================================')
    print(
        'Current Python is not running in native free-threaded mode.'
    )
    print(
        'Restarting automatically with Python 3.14t and GIL disabled...'
    )
    print()
    print(
        'Command: '
        +
        subprocess.list2cmdline(
            relaunch_args
        )
    )
    print('==============================================')
    print()


    relaunch_environment = dict(
        os.environ
    )

    relaunch_environment[
        'NAU_FREE_THREADED_RELAUNCH'
    ] = '1'


    try:

        child = subprocess.Popen(
            relaunch_args,
            cwd=str(
                Path(
                    __file__
                ).resolve().parent
            ),
            env=relaunch_environment
        )

    except OSError as error:

        raise RuntimeError(
            'Could not relaunch NAU POS with Python 3.14t. '
            f'Launcher error: {error}'
        ) from error


    # IMPORTANT:
    # Keep this launcher process attached to the free-threaded child.
    # Older builds exited immediately here, which could leave a stale
    # 3.14t child serving port 8000 while the user thought they had
    # restarted the server.
    try:

        return_code = child.wait()

    except KeyboardInterrupt:

        print()
        print(
            'Stopping free-threaded NAU server child...'
        )

        try:

            child.terminate()

        except Exception:

            pass

        try:

            return_code = child.wait(
                timeout=5
            )

        except Exception:

            try:

                child.kill()

            except Exception:

                pass

            return_code = 130


    raise SystemExit(
        return_code
    )



def require_native_free_threading():

    if not FREE_THREADED_BUILD:

        raise RuntimeError(
            'NAU POS is not running on the Python 3.14t free-threaded build.'
        )


    if GIL_ENABLED is not False:

        raise RuntimeError(
            'NAU POS is running on free-threaded Python, but the GIL is enabled.'
        )



def _native_thread_probe_worker(
    start_barrier,
    duration_seconds,
    result,
    result_index
):

    start_barrier.wait()

    native_id = getattr(
        threading.current_thread(),
        'native_id',
        None
    )

    started = time.perf_counter()
    deadline = started + duration_seconds
    value = result_index + 1
    iterations = 0

    while time.perf_counter() < deadline:

        value = (
            (
                value * 1664525
                +
                1013904223
            )
            &
            0xFFFFFFFF
        )

        value ^= (
            value >>
            13
        )

        iterations += 1

    result[
        result_index
    ] = {
        'thread':
            threading.current_thread().name,

        'native_id':
            native_id,

        'iterations':
            iterations,

        'value':
            value
    }



def run_native_thread_self_test():

    ensure_native_free_threading()
    require_native_free_threading()

    workers = max(
        2,
        min(
            4,
            LOGICAL_CPU_COUNT
        )
    )

    duration_seconds = 1.5

    barrier = threading.Barrier(
        workers
    )

    results = [
        None
        for _ in range(
            workers
        )
    ]

    threads = [
        threading.Thread(
            target=
                _native_thread_probe_worker,

            args=(
                barrier,
                duration_seconds,
                results,
                index
            ),

            name=
                f'nau-self-test-{index + 1}'
        )

        for index in range(
            workers
        )
    ]


    wall_start = time.perf_counter()
    cpu_start = time.process_time()


    for thread in threads:

        thread.start()


    for thread in threads:

        thread.join()


    wall_seconds = (
        time.perf_counter()
        -
        wall_start
    )

    cpu_seconds = (
        time.process_time()
        -
        cpu_start
    )

    cpu_to_wall = (
        cpu_seconds
        /
        wall_seconds

        if wall_seconds > 0

        else 0
    )


    print()
    print('==============================================')
    print('       NAU POS NATIVE THREAD SELF TEST')
    print('==============================================')
    print(f'Python: {sys.version}')
    print(f'Logical CPUs: {LOGICAL_CPU_COUNT}')
    print(f'Free-threaded build: {FREE_THREADED_BUILD}')
    print(f'GIL enabled: {GIL_ENABLED}')
    print(f'Workers: {workers}')
    print(f'Wall time: {wall_seconds:.3f}s')
    print(f'Process CPU time: {cpu_seconds:.3f}s')
    print(f'CPU / wall ratio: {cpu_to_wall:.2f}x')
    print()
    print('Worker OS thread IDs:')

    for item in results:

        print(
            f'  {item["thread"]}: '
            f'native_id={item["native_id"]}, '
            f'iterations={item["iterations"]}'
        )

    print()
    print(
        'PASS: Python 3.14t is running with the GIL disabled. '
        'These worker threads are allowed to execute Python code '
        'in parallel on separate CPU cores.'
    )
    print('==============================================')
    print()

    return 0




# Remote Founder API, Cloudflare Tunnel connector, and FFmpeg camera gateway removed from this public POS edition.


# Desktop dashboard and tray icon have been removed.


# Non-destructive startup diagnostics. Runs after the HTTP listeners have started;
# each network probe has its own deadline. This does not gate local POS service.
def _nau_startup_self_test(google_enabled, selected=None):
    """Non-destructive probes; selected is an optional set of probe names."""
    selected = set(selected) if selected is not None else None
    def wanted(name):
        return selected is None or name in selected
    import urllib.request
    import urllib.error

    results = []

    def record(name, status, detail=''):
        detail = str(detail).replace('\n', ' ')[:180]
        if not wanted(name):
            return
        results.append((name, status, detail))
        print(f'[{status:4}] {name}' + (f' | {detail}' if detail else ''), flush=True)

    def http_json(url, timeout=5):
        import json as _json
        request = urllib.request.Request(url, headers={'User-Agent': 'NAU-Startup-Diagnostics/1.0', 'Accept': 'application/json'})
        with urllib.request.urlopen(request, timeout=timeout) as response:
            data = response.read(65536)
            return response.status, _json.loads(data)

    def probe(name, func):
        if not wanted(name):
            return
        try:
            status, detail = func()
            record(name, status, detail)
        except Exception as error:
            record(name, 'FAIL', f'{type(error).__name__}: {error}')

    print('\n' + '=' * 46, flush=True)
    print('          NAU POS STARTUP SELF-TEST', flush=True)
    print('=' * 46, flush=True)

    record('Python free-threading', 'PASS' if FREE_THREADED_PARALLELISM else 'FAIL',
           'GIL disabled' if FREE_THREADED_PARALLELISM else 'Native parallelism unavailable')

    def local_pos():
        # A TCP handshake verifies the listening socket without triggering a POS
        # endpoint that might mutate data or require an authenticated session.
        import socket
        with socket.create_connection(('127.0.0.1', PORT), timeout=3):
            return 'PASS', f'Port {PORT} accepts connections'
    probe('POS listener', local_pos)

    def storage():
        # Write only an isolated disposable file; never modify a database record.
        import tempfile
        root = Path(database_folder)
        if not root.is_dir():
            raise RuntimeError('Database directory missing')
        with tempfile.NamedTemporaryFile(prefix='.nau_health_', suffix='.tmp', dir=str(root), delete=False) as tmp:
            temp_name = tmp.name
            tmp.write(b'NAU_DIAGNOSTIC')
            tmp.flush()
            os.fsync(tmp.fileno())
        try:
            if Path(temp_name).read_bytes() != b'NAU_DIAGNOSTIC':
                raise RuntimeError('Temporary storage read-back failed')
        finally:
            Path(temp_name).unlink(missing_ok=True)
        return 'PASS', f'{storage_mode} storage read/write OK'
    probe('Database storage', storage)

    def backup_storage():
        if storage_mode != 'MAIN':
            return 'WARN', 'Running on backup storage; main storage is unavailable'
        if not Path(backup_data_root).is_dir():
            raise RuntimeError('Backup folder unavailable')
        if not Path(backup_data_root, 'DATABASE').is_dir():
            return 'WARN', 'Backup folder exists but DATABASE folder is missing'
        return 'PASS', 'Backup DATABASE folder accessible (not a full integrity audit)'
    probe('Local backup storage', backup_storage)

    if wanted('Google Drive') or wanted('Google Sheets'):
        if not google_enabled:
            record('Google Drive', 'WARN', 'Google Finance integration disabled')
            record('Google Sheets', 'WARN', 'Google Finance integration disabled')
        else:
            # Never launch an OAuth browser during startup diagnostics.
            try:
                from googleapiclient.discovery import build
                from google_auth_httplib2 import AuthorizedHttp
                import httplib2
                credentials = google_finance_credentials(interactive=False)
                drive = build('drive', 'v3', http=AuthorizedHttp(credentials, http=httplib2.Http(timeout=8)), cache_discovery=False)
                folders = drive.files().list(
                    q="name = 'FINANCE' and mimeType = 'application/vnd.google-apps.folder' and 'root' in parents and trashed = false",
                    fields='files(id,name)', pageSize=100).execute(num_retries=0).get('files', [])
                record('Google Drive', 'PASS', 'Authenticated Drive API read succeeded')
                if not folders:
                    record('Google Sheets', 'WARN', 'FINANCE folder not found; run Finance sync first')
                else:
                    sheet_file = None
                    for folder in folders:
                        candidates = drive.files().list(
                            q="mimeType = 'application/vnd.google-apps.spreadsheet' and '" + folder['id'] + "' in parents and trashed = false",
                            fields='files(id,name)', pageSize=100).execute(num_retries=0).get('files', [])
                        if candidates:
                            sheet_file = max(candidates, key=lambda x: x['name'])
                            break
                    if not sheet_file:
                        record('Google Sheets', 'WARN', 'No Finance spreadsheet found; run Finance sync first')
                    else:
                        sheets = build('sheets', 'v4', http=AuthorizedHttp(credentials, http=httplib2.Http(timeout=8)), cache_discovery=False)
                        info = sheets.spreadsheets().get(spreadsheetId=sheet_file['id'], fields='properties(title),sheets(properties(title))').execute(num_retries=0)
                        names = {item.get('properties', {}).get('title') for item in info.get('sheets', [])}
                        missing = set(calendar.month_name[1:]) - names
                        if missing:
                            record('Google Sheets', 'WARN', f'Sheet readable; {len(missing)} month tab(s) missing')
                        else:
                            record('Google Sheets', 'PASS', 'Finance spreadsheet and 12 month tabs readable')
            except Exception as error:
                # Distinguish failed authentication / connectivity from a Sheets
                # failure we did not actually reach.
                record('Google Drive', 'FAIL', f'{type(error).__name__}: {error}')
                if not any(name == 'Google Sheets' for name, _, _ in results):
                    record('Google Sheets', 'WARN', 'Not verified because Google Drive check failed')

    passed = sum(status == 'PASS' for _, status, _ in results)
    warned = sum(status == 'WARN' for _, status, _ in results)
    failed = sum(status == 'FAIL' for _, status, _ in results)
    print('-' * 46, flush=True)
    print(f'SELF-TEST COMPLETE | {passed} PASS | {warned} WARN | {failed} FAIL', flush=True)
    print('Local POS continues running regardless of external service results.', flush=True)
    print('=' * 46 + '\n', flush=True)
    try:
        write_log(f'STARTUP SELF-TEST | PASS={passed} WARN={warned} FAIL={failed} | ' +
                  '; '.join(f'{name}={status}' for name, status, _ in results))
    except Exception:
        pass

# Server diagnostics are emitted to stdout/stderr for the EXE's Server tab.


def start_server():

    global active_data_root, storage_mode


    # If this file was started with ordinary "python server.py",
    # automatically relaunch it under Python 3.14t with the GIL disabled.
    ensure_native_free_threading()

    # The process reaching this point must now be genuinely free-threaded.
    require_native_free_threading()


    selected_root, first_run, existing_data, needs_initial_backup = (
        resolve_redundant_storage()
    )

    configure_data_paths(selected_root)

    # Remove orphaned atomic-write / mirror temp files from previous crashes
    # and any abandoned local Google backup staging snapshot.
    cleanup_nau_temp_artifacts()

    # A genuinely new MAIN database is initialized before the first mirror.
    initialize_database()

    # Persist both roots before profile/Google setup modifies AppData settings.
    save_storage_locations(
        main_data_root,
        backup_data_root,
        active_data_root
    )

    initialize_profiles()

    google_enabled = configure_google_finance(
        force='--configure-google' in sys.argv
    )

    # First setup (or migration from the old single-database settings) creates
    # a complete live backup before the HTTP server begins accepting requests.
    if storage_mode == 'MAIN':
        try:
            sync_storage_tree(
                active_data_root,
                backup_data_root
            )
            print(
                f'Live backup synchronized: {backup_data_root}'
            )
        except Exception as error:
            print(
                f'WARNING: Initial backup synchronization failed: {error}',
                flush=True
            )
            # Server-only storage management: console warning is sufficient.

    # If startup had to use BACKUP because MAIN was missing, announce it in
    # console, server log, and the POS health/status payload.
    if storage_mode == 'BACKUP':
        message = (
            'DATABASE FAILOVER | Main database cannot be accessed or found. '
            f'Using backup database: {active_data_root}'
        )
        print()
        print('!' * 72)
        print(message)
        print('!' * 72)
        print()
        _write_storage_event_to_both(message)

    print(
        f'Active data: {active_data_root} '
        f'({"MAIN" if storage_mode == "MAIN" else "BACKUP"})'
    )
    print(f'Main data: {main_data_root}')
    print(f'Backup data: {backup_data_root}')
    print(f'Settings: {settings_file}')
    print(
        f'Running server code: {Path(__file__).resolve()} | {SERVER_BUILD}'
    )
    print(
        f'Server process PID: {os.getpid()}'
    )

    server = NAUThreadPoolHTTPServer(
        (
            HOST,
            PORT
        ),
        NAURequestHandler,
        max_workers=HTTP_WORKER_THREADS
    )

    threading.Thread(
        target=storage_monitor_loop,
        name='nau-storage-monitor',
        daemon=True
    ).start()

    if google_enabled:
        threading.Thread(
            target=finance_auto_sync_loop,
            args=(not google_token_file.exists(),),
            name='google-finance-sync',
            daemon=True
        ).start()

        threading.Thread(
            target=google_drive_backup_loop,
            name='google-drive-nau-backup',
            daemon=True
        ).start()

    print()
    print('==============================================')
    print('              NAU POS SERVER')
    print('==============================================')
    print(f'Server: http://{HOST}:{PORT}')
    print(f'Database: {database_folder}')
    print(f'Storage mode: {storage_mode}')
    print(f'Logical CPUs: {LOGICAL_CPU_COUNT}')
    print(f'HTTP worker threads: {HTTP_WORKER_THREADS}')


    print('Python free-threaded build: YES')
    print('GIL: DISABLED')
    print('Native parallel Python threads: ENABLED')
    print('Press CTRL+C to stop.')
    print('==============================================')
    print()

    write_log(
        f'SERVER STARTED | '
        f'HOST={HOST} | '
        f'PORT={PORT} | '
        f'STORAGE={storage_mode} | '
        f'HTTP_THREADS={HTTP_WORKER_THREADS} | '
        f'GIL_ENABLED={GIL_ENABLED} | '
        f'FREE_THREADED={FREE_THREADED_PARALLELISM} | '
        f'ACTIVE={active_data_root} | '
        f'BACKUP={backup_data_root} | '
        f'REMOTE_FOUNDER_API=DISABLED'
    )

    # The listener is active while this daemon checks network services.
    # Diagnostics never block the POS from accepting requests.
    threading.Thread(
        target=_nau_startup_self_test,
        args=(google_enabled,),
        name='nau-startup-self-test',
        daemon=True,
    ).start()

    # Console controls run separately so input() never blocks HTTP requests.
    # Non-interactive packaged builds simply receive EOF and exit this thread.
    if sys.stdin is not None and sys.stdin.isatty():
        threading.Thread(
            target=nau_server_console_commands,
            args=(google_enabled,),
            name='nau-console-commands',
            daemon=True,
        ).start()

    try:
        server.serve_forever()

    except KeyboardInterrupt:
        print()
        print('Stopping NAU POS server...')

    finally:
        storage_monitor_stop.set()
        server.server_close()
        try:
            write_log(
                'SERVER STOPPED'
            )
        except Exception:
            pass


if __name__ == '__main__':

    if (
        '--thread-self-test'
        in
        sys.argv
    ):

        raise SystemExit(
            run_native_thread_self_test()
        )


    start_server()
